-- ─────────────────────────────────────────────────────────────
-- CallWrap 시연용 더미 데이터
--
-- 예전 AdminDemoDataSeeder(@Profile("local") ApplicationRunner)를 대체한다.
-- 앱 기동과 분리해서, 넣고 싶을 때만 넣고 시연 전엔 통째로 지울 수 있게 SQL로 옮겼다.
--
--   넣기 : docker exec -i callwrap-spring-postgres psql -U callwrap -d callwrap < scripts/demo-data.sql
--   지우기: docker exec -i callwrap-spring-postgres psql -U callwrap -d callwrap < scripts/demo-data-clean.sql
--
-- 이 스크립트가 만든 것은 전부 source_request_id LIKE 'DEMO-%' / login_id LIKE 'demo-%' /
-- phone LIKE '010-77%'로 표시된다. FAQ만은 표식을 못 붙여서(시연 화면에 노출되므로)
-- Flyway V6이 심은 고정 id 5건을 제외한 전부를 clean이 지운다.
-- admin/test 계정은 DevAccountSeeder가 기동 시 따로 만들므로 여기서 건드리지 않는다.
--
-- 설계 기준(피그마 "17 관리자 · 개요"):
--   · 오늘 콜은 09~20시에 4·8·12·16·11·7·10·15·19·13·8·5 = 128건으로 흩뿌린다.
--     시간대별 차트가 한두 개 막대로 쪼그라들지 않게 하려는 것이 핵심이다.
--   · 상담사 12명은 처리 건수가 서로 다르게(그라데이션 막대가 의미를 갖게) 배분한다.
--   · 상담유형·중분류 비중은 피그마 도넛 수치(30/20/15/11/9/7/5/3, 32/26/17/12/9/4)에 맞춘다.
--   · 상담유형·중분류·소분류는 web/src/lib/classificationOptions.ts에 실재하는 값만 쓴다.
--     (예전 시더는 목록에 없는 '규정및지침문의'·'단순정보문의'를 넣어 드롭다운이 빈 채로 떴다.)
-- ─────────────────────────────────────────────────────────────

BEGIN;

-- 재실행해도 중복되지 않게 먼저 비운다. calls의 자식 테이블은 ON DELETE CASCADE다.
-- FAQ는 질문 문구에 표식을 두지 않는다(시연 화면에 '[데모]' 같은 접두사가 보이면 안 된다).
-- 대신 Flyway V6이 심어둔 5건(id가 11111111-…로 고정)만 남기고 나머지를 지운다.
DELETE FROM faq_entry_revisions
 WHERE faq_entry_id IN (SELECT id FROM faq_entries WHERE id::text NOT LIKE '11111111-1111-4111-8111-%');
DELETE FROM faq_entries WHERE id::text NOT LIKE '11111111-1111-4111-8111-%';
DELETE FROM calls WHERE source_request_id LIKE 'DEMO-%';
DELETE FROM complainants WHERE phone LIKE '010-77%';
DELETE FROM counselors WHERE login_id LIKE 'demo-%';

-- ── 1. 상담사 12명 ────────────────────────────────────────
-- 비밀번호는 전부 'demo' (bcrypt). rank가 낮을수록 처리 건수가 많다(피그마 막대 순서).
-- negative_base: 최근 7일 부정 발화 평균의 기준값. CounselorStateEvaluator 임계값이
--   0.45 이상 → 휴식 권장 / 0.25 이상 → 주의 / 그 아래 → 양호 이므로
--   세 상태가 모두 화면에 보이도록 의도적으로 흩어 놓았다.
CREATE TEMP TABLE tmp_counselor (rank INT, id UUID, login_id TEXT, name TEXT, team TEXT,
                                 share INT, negative_base NUMERIC, malicious_quota INT) ON COMMIT DROP;
