    ( 4, gen_random_uuid(), 'demo-jung', '정민원', '상담2팀',  9, 0.09,  1),
    ( 5, gen_random_uuid(), 'demo-han',  '한고객', '상담2팀',  9, 0.47, 10),  -- 휴식 권장
    ( 6, gen_random_uuid(), 'demo-noh',  '노경식', '상담2팀',  8, 0.18,  1),
    ( 7, gen_random_uuid(), 'demo-seo',  '서지완', '상담3팀',  7, 0.10,  1),
