    ( 9, gen_random_uuid(), 'demo-ryu',  '류지호', '상담3팀',  6, 0.35,  3),  -- 주의
    (10, gen_random_uuid(), 'demo-shin', '신가온', '상담3팀',  5, 0.07,  1),
