INSERT INTO counselors (id, login_id, password_hash, name, team, role, created_at, updated_at)
SELECT id, login_id, '$2y$10$Rzeo7iCd07qqup8smFMQlun1vY1jX645pwiju/FcbsrO26kmxYdOG', name, team,
       'COUNSELOR', now() - INTERVAL '90 days', now() - INTERVAL '90 days'
FROM tmp_counselor;

-- share를 0~99 슬롯으로 펼쳐서 콜을 배분한다(합계 100).
CREATE TEMP TABLE tmp_counselor_slot (slot INT, counselor_id UUID, rank INT,
                                      negative_base NUMERIC, malicious_quota INT) ON COMMIT DROP;
INSERT INTO tmp_counselor_slot
SELECT (ROW_NUMBER() OVER (ORDER BY c.rank) - 1)::int, c.id, c.rank, c.negative_base, c.malicious_quota
FROM tmp_counselor c, LATERAL generate_series(1, c.share);

