CREATE TEMP TABLE tmp_customer_slot (slot INT, customer_id UUID) ON COMMIT DROP;
INSERT INTO tmp_customer_slot
SELECT (ROW_NUMBER() OVER (ORDER BY c.idx) - 1)::int, c.id
FROM tmp_customer c, LATERAL generate_series(1, c.share);

-- ── 3. 분류 슬롯 (0~99) ───────────────────────────────────
-- 상담유형: 피그마 도넛 비중 그대로. CONSULTATION_TYPES에 있는 8개만 쓴다.
CREATE TEMP TABLE tmp_type_slot (slot INT, type TEXT) ON COMMIT DROP;
INSERT INTO tmp_type_slot
SELECT (ROW_NUMBER() OVER () - 1)::int, t.name
FROM (VALUES ('사용법문의', 30), ('시스템오류', 20), ('자료확인', 15), ('정책 및 지침문의', 11),
             ('고객PC환경', 9), ('자료보정', 7), ('기능개선', 5), ('기타', 3)) AS t(name, w),
     LATERAL generate_series(1, t.w);

-- 중분류·소분류는 항상 짝으로 뽑는다 — 소분류가 그 중분류에 실제로 속한 값이 되도록
-- (SUBCATEGORIES_BY_CATEGORY 매핑을 그대로 옮긴 것). 따로 뽑으면 정합이 깨진다.
