        ('결제및비용지급',   '결제방법 및 오류',      8),
        ('결제및비용지급',   '결제내역',              6),
        ('결제및비용지급',   '과오결제',              4),
        ('결제및비용지급',   '서비스비용 지급',       4),
        ('결제및비용지급',   '가산단가',              2),
        ('결제및비용지급',   '교통비 지급',           2),
        ('제공인력관리',     '자격 및 교육',          7),
        ('제공인력관리',     '급여등록',              6),
        ('제공인력관리',     '제공인력 정보',         4),
        ('제공기관관리',     '제공기관운영',          7),
        ('제공기관관리',     '제공기관정보',          5),
        ('지자체사업관리',   '사업운영 및 기존정보',  4),
        ('지자체사업관리',   '예탁금관리',            3),
        ('지자체사업관리',   '행복e음 연계',          2),
        ('부정사용',         '신고절차',              2),
