-- ── 4. 콜 뼈대 ────────────────────────────────────────────
-- 세 덩어리로 나눈다.
--   · 오늘 128건  — 피그마 17의 시간대별 분포 그대로. 개요 첫 화면이 이걸로 그려진다.
--   · 지난 6일 30건/일 = 180건 — 7일 감정 추이·상담사 상태 판정이 이 창을 본다.
--   · 지난 5개월 100건/월 = 500건 — 민원인 "문의 추이 최근 6개월"용.
-- 마지막 덩어리가 없으면 이번 달만 막대가 솟고 나머지 다섯 달이 0으로 비어, 추이가 아니라
-- 스파이크 하나로 보인다. 합계 808건.
CREATE TEMP TABLE tmp_slot (n INT, day_offset INT, hour INT, minute INT, month_offset INT) ON COMMIT DROP;
INSERT INTO tmp_slot (n, day_offset, hour, minute, month_offset)
SELECT ROW_NUMBER() OVER (ORDER BY s.month_offset, s.day_offset DESC, s.hour, s.i)::int,
       s.day_offset, s.hour, ((s.i * 7 + s.hour * 13) % 60), s.month_offset
FROM (
    -- 오늘 (피그마 17 시간대별 처리 추이)
    SELECT 0 AS month_offset, 0 AS day_offset, h.hour, g.i
    FROM (VALUES (9, 4), (10, 8), (11, 12), (12, 16), (13, 11), (14, 7),
                 (15, 10), (16, 15), (17, 19), (18, 13), (19, 8), (20, 5)) AS h(hour, cnt),
         LATERAL generate_series(1, h.cnt) AS g(i)
    UNION ALL
    -- 지난 6일 (하루 30건)
    SELECT 0, d.day_offset, h.hour, g.i
    FROM generate_series(1, 6) AS d(day_offset),
         (VALUES (9, 2), (10, 3), (11, 4), (12, 4), (13, 3), (14, 2),
                 (15, 3), (16, 3), (17, 4), (18, 2)) AS h(hour, cnt),
         LATERAL generate_series(1, h.cnt) AS g(i)
    UNION ALL
    -- 지난 5개월 (월 100건). day_offset은 해당 월 안에서 1~28일에 흩어지도록 뒤에서 다시 쓴다.
    SELECT m.month_offset, ((g.i * 13) % 28) + 1, 9 + (g.i % 10), g.i
    FROM generate_series(1, 5) AS m(month_offset),
         generate_series(1, 100) AS g(i)
) AS s;

-- 각 콜의 속성을 n에서 결정론적으로 뽑는다. 서로 다른 소수를 곱해 축끼리 상관되지 않게 한다.
CREATE TEMP TABLE tmp_call AS
SELECT
    gen_random_uuid()                                    AS id,
    s.n,
    s.day_offset,
    s.month_offset,
    -- 이번 달 덩어리는 오늘로부터 day_offset일 전, 과거 달 덩어리는 그 달의 day_offset일.
    CASE WHEN s.month_offset = 0
         THEN (CURRENT_DATE - s.day_offset)::timestamp
         ELSE (date_trunc('month', CURRENT_DATE) - make_interval(months => s.month_offset)
               + make_interval(days => s.day_offset - 1))::timestamp
    END + make_interval(hours => s.hour, mins => s.minute)  AS started_at,
    cs.counselor_id,
    cs.rank                                              AS counselor_rank,
    cs.negative_base,
    cs.malicious_quota,
    cu.customer_id,
    ts.type,
    ct.category,
    ct.subcategory,
    (150 + (s.n * 37) % 420)                             AS duration_sec,
    -- 부정 발화는 상담사 기준값에 날짜별 흔들림(±0.06)을 준다.
    -- 예전 시더는 상담사마다 상수를 써서 7일 추이 차트가 완전히 평평했다.
    GREATEST(0.02, LEAST(0.97,
        cs.negative_base + (((cs.rank * 3 + s.day_offset * 5) % 7) - 3) * 0.02))::double precision
                                                         AS negative_score
FROM tmp_slot s
JOIN tmp_counselor_slot cs ON cs.slot = (s.n * 37) % 100
JOIN tmp_customer_slot  cu ON cu.slot = (s.n * 53) % 100
JOIN tmp_type_slot      ts ON ts.slot = (s.n * 61) % 100
JOIN tmp_cat_slot       ct ON ct.slot = (s.n * 71) % 100;

-- 등급.
-- 상담사 상태(양호/주의/휴식 권장)는 "최근 7일" 창의 악성콜 건수에도 걸려 있어서
-- (CounselorStateEvaluator: 2건 이상 주의, 4건 이상 휴식 권장) 악성콜을 확률로 뿌리면
-- 양호여야 할 상담사까지 전부 휴식 권장으로 떨어진다. 그래서 두 구간을 분리한다.
--   · 최근 7일: 상담사별 malicious_quota를 정확히 지킨다 → 상태가 의도대로 나온다.
--   · 그 이전  : 상태 판정에 안 들어가므로 일괄 8%로 뿌린다 → 도넛·이력이 자연스러워진다.
-- 각 구간 안에서는 콜을 뒤섞어(n * 7919 % 100003) 특정 날짜에 몰리지 않게 한다.
CREATE TEMP TABLE tmp_call_graded AS
SELECT c.*,
       CASE
           WHEN c.is_recent AND c.shuffled <= c.malicious_quota                 THEN '악성콜'
           WHEN c.is_recent AND c.shuffled <= c.malicious_quota + c.praise_q    THEN '칭찬콜'
           WHEN NOT c.is_recent AND c.shuffled % 12 = 0                         THEN '악성콜'
           WHEN NOT c.is_recent AND c.shuffled % 12 IN (1, 2)                   THEN '칭찬콜'
           ELSE '일반'
       END AS grade
FROM (
    SELECT t.*,
           t.month_offset = 0 AS is_recent,
           ROW_NUMBER() OVER (PARTITION BY t.counselor_id, (t.month_offset = 0)
                              ORDER BY (t.n * 7919) % 100003) AS shuffled,
           GREATEST(3, (COUNT(*) OVER (PARTITION BY t.counselor_id, (t.month_offset = 0)) * 18 / 100)) AS praise_q
    FROM tmp_call t
) c;

-- 상태: 지난 날짜 콜은 이미 처리가 끝난 것으로 본다(현실적이기도 하고, 상담사 대기열이
-- 며칠치로 불어나지 않게 하려는 것도 있다). 검토 대기/실패는 오늘 콜에서만 나온다.
CREATE TEMP TABLE tmp_call_final AS
SELECT g.*,
       CASE
           WHEN g.is_today AND g.today_seq <= 4  THEN 'NEEDS_HUMAN_REVIEW'
           WHEN g.is_today AND g.today_seq <= 6  THEN 'DONE'
           WHEN g.is_today AND g.today_seq  = 7  THEN 'FAILED'
           ELSE 'CONFIRMED'
       END AS status
FROM (
    SELECT c.*,
           (c.month_offset = 0 AND c.day_offset = 0) AS is_today,
           ROW_NUMBER() OVER (PARTITION BY c.month_offset, c.day_offset
                              ORDER BY (c.n * 4133) % 100003) AS today_seq,
           ((c.n * 4133) % 100003) % 25 = 0 AS needs_followup,
           ((c.n * 3571) % 100003) % 17 = 0 AS needs_faq
    FROM tmp_call_graded c
) g;

INSERT INTO calls (id, counselor_id, complainant_id, audio_path, status, retry_count,
                   source_request_id, call_started_at, call_duration_sec,
                   counselor_negative_score, created_at, updated_at)
SELECT id, counselor_id, customer_id, NULL, status, 0,
       'DEMO-' || n, started_at, duration_sec, negative_score,
       -- created_at이 반드시 실제 통화 시각이어야 한다:
       -- 개요 "시간대별 처리 추이"(CallRepository.countTodayByHour)가 call_started_at이 아니라
       -- created_at을 EXTRACT(HOUR ...)로 집계하기 때문이다.
       started_at, started_at
FROM tmp_call_final;

-- ── 5. 분석 결과 ──────────────────────────────────────────
-- Judgment JSONB는 {value, confidence, evidenceIndices} — global/common/Judgment.java와 같은 모양.
INSERT INTO analysis_results (
    id, call_id, confirmed_by_counselor_id, summary, consultation_type, consultation_category,
    consultation_subcategory, grade, needs_followup, needs_faq, failures, utterance_sentiments,
    edited_fields, confirmed_at, review_sec, reconfirm_count, created_at)
SELECT
    gen_random_uuid(),
    c.id,
    CASE WHEN c.status = 'CONFIRMED' THEN c.counselor_id END,
    jsonb_build_object(
        'value', jsonb_build_object(
            'title', c.subcategory || CASE c.grade WHEN '악성콜' THEN ' 항의 상담'
                                                   WHEN '칭찬콜' THEN ' 감사 상담'
                                                   ELSE ' 문의' END,
            'inquiry', c.subcategory || ' 관련해서 처리 방법을 문의하셨습니다.',
            'resolution', c.subcategory || ' 처리 절차와 확인 경로를 안내드렸습니다.'),
        'confidence', conf.summary_conf, 'evidenceIndices', '[0, 2]'::jsonb),
    jsonb_build_object('value', c.type,        'confidence', conf.type_conf, 'evidenceIndices', '[0, 1]'::jsonb),
    jsonb_build_object('value', c.category,    'confidence', conf.cat_conf,  'evidenceIndices', '[0, 1]'::jsonb),
    jsonb_build_object('value', c.subcategory, 'confidence', conf.sub_conf,  'evidenceIndices', '[0, 3]'::jsonb),
    jsonb_build_object('value', c.grade,       'confidence', conf.grade_conf,'evidenceIndices', '[2, 4]'::jsonb),
    jsonb_build_object('value', c.needs_followup, 'confidence', conf.type_conf, 'evidenceIndices', '[4]'::jsonb),
    jsonb_build_object('value', c.needs_faq,      'confidence', conf.cat_conf,  'evidenceIndices', '[1]'::jsonb),
    -- failures는 문자열 배열이 아니라 PipelineFailure(stage, reason) 객체 배열이다.
    -- 문자열을 넣으면 목록 조회 시 역직렬화가 터져 그 페이지 전체가 500으로 떨어진다.
    CASE WHEN c.status = 'FAILED'
         THEN jsonb_build_array(jsonb_build_object(
                  'stage', 'TRANSCRIPT',
                  'reason', '전사 신뢰도가 기준치를 밑돌아 재시도 후에도 분석을 확정하지 못했습니다.'))
         ELSE '[]'::jsonb END,
    -- 고객 1 + 상담사 2 발화의 감정 점수. 상담사 점수 평균이 calls.counselor_negative_score와 맞물린다.
    jsonb_build_array(
        jsonb_build_object('utteranceIndex', 0, 'speaker', '고객',
                           'score', CASE c.grade WHEN '악성콜' THEN -0.85 WHEN '칭찬콜' THEN 0.62 ELSE -0.12 END),
        jsonb_build_object('utteranceIndex', 1, 'speaker', '상담사', 'score', -(c.negative_score - 0.03)),
        jsonb_build_object('utteranceIndex', 3, 'speaker', '상담사', 'score', -(c.negative_score + 0.03))),
    '[]'::jsonb,
    CASE WHEN c.status = 'CONFIRMED' THEN c.started_at + make_interval(secs => c.duration_sec + 120) END,
    CASE WHEN c.status = 'CONFIRMED' THEN 45 + (c.n * 29) % 140 END,
    0,
    c.started_at
FROM (
    SELECT f.id, f.n, f.counselor_id, f.status, f.grade, f.type, f.category, f.subcategory,
           f.started_at, f.duration_sec, f.negative_score, f.needs_followup, f.needs_faq
    FROM tmp_call_final f
) c
CROSS JOIN LATERAL (SELECT
    -- 확신도를 흩어 놓아야 검토 화면의 "확신 우선 트리아지"(high/medium/low 배지)가 셋 다 보인다.
    (0.62 + ((c.n * 17) % 38) / 100.0)::double precision AS type_conf,
    (0.60 + ((c.n * 23) % 40) / 100.0)::double precision AS cat_conf,
    (0.58 + ((c.n * 31) % 41) / 100.0)::double precision AS sub_conf,
    (0.70 + ((c.n * 13) % 30) / 100.0)::double precision AS grade_conf,
    (0.66 + ((c.n * 19) % 33) / 100.0)::double precision AS summary_conf
) conf;

-- ── 6. 전사문 ─────────────────────────────────────────────
-- Utterance JSONB는 {index, speaker, text, start, end, confidence} — transcript/domain/Utterance.java.
-- speaker는 Speaker enum의 @JsonValue인 한글 라벨('고객'/'상담사')이어야 한다.
INSERT INTO transcripts (id, call_id, utterances, retry_iteration, created_at)
SELECT gen_random_uuid(), c.id,
    jsonb_build_array(
        jsonb_build_object('index', 0, 'speaker', '고객',   'start', 0.0,  'end', 7.4,  'confidence', 0.96,
            'text', '안녕하세요, ' || c.subcategory || ' 관련해서 여쭤볼 게 있어서 전화드렸습니다.'),
        jsonb_build_object('index', 1, 'speaker', '상담사', 'start', 7.8,  'end', 12.1, 'confidence', 0.98,
            'text', '네 고객님, ' || c.subcategory || ' 문의 주셨군요. 확인 후 안내드리겠습니다.'),
        jsonb_build_object('index', 2, 'speaker', '고객',   'start', 12.5, 'end', 21.9, 'confidence', 0.94,
            'text', CASE c.grade
                WHEN '악성콜' THEN '지난번에도 똑같이 안내받았는데 아직도 해결이 안 됐어요. 몇 번을 더 전화해야 하는 겁니까?'
                WHEN '칭찬콜' THEN '지난번에 안내해 주신 대로 하니까 바로 해결됐어요. 정말 감사합니다.'
                ELSE '제가 신청한 건이 어떻게 처리되고 있는지 확인이 안 돼서요.' END),
        jsonb_build_object('index', 3, 'speaker', '상담사', 'start', 22.4, 'end', 33.7, 'confidence', 0.97,
            'text', '확인해 보니 ' || c.category || ' 항목으로 접수되어 있습니다. ' || c.subcategory || ' 처리 절차를 순서대로 안내드릴게요.'),
        jsonb_build_object('index', 4, 'speaker', '고객',   'start', 34.2, 'end', 39.8, 'confidence', 0.95,
            'text', '알겠습니다. 그러면 언제쯤 결과를 확인할 수 있을까요?'),
        jsonb_build_object('index', 5, 'speaker', '상담사', 'start', 40.3, 'end', 49.6, 'confidence', 0.98,
            'text', '접수일 기준 3영업일 이내에 처리되며, 진행 상황은 홈페이지 조회 메뉴에서 확인하실 수 있습니다.')),
    0, c.started_at
FROM tmp_call_final c;

-- ── 7. 후속 처리 이력 ─────────────────────────────────────
-- needs_followup으로 표시된 콜(= 상단바 "진행 중")에만 붙인다.
INSERT INTO followup_notes (id, call_id, counselor_id, content, created_at)
SELECT gen_random_uuid(), f.id, f.counselor_id,
       CASE (f.n % 3)
           WHEN 0 THEN '담당 부서에 확인 요청 전달했습니다. 회신 오는 대로 민원인께 유선 안내 예정입니다.'
           WHEN 1 THEN '요청하신 서류 재발급 신청 접수했습니다. 처리 완료까지 2~3일 소요 예정입니다.'
           ELSE        '지자체 담당자와 통화하여 처리 기준 확인했습니다. 민원인께 재안내 필요합니다.'
       END,
       f.started_at + INTERVAL '35 minutes'
FROM tmp_call_final f
WHERE f.needs_followup AND f.status = 'CONFIRMED';

-- ── 8. FAQ 검수 대기 초안 ─────────────────────────────────
-- 콜에서 자동 생성된 것으로 보이는 초안들. FAQ 검수 화면의 시연 대상이 이쪽이다
-- (검수 대기 → 신규 등록/FAQ 업데이트/추가 안 함). 게시된 기존 FAQ는 8b에서 넣는다.
-- sample_call_ids 개수와 source_call_count를 일치시킨다 — 예전 시더는 "근거 콜 9건"이라
-- 써 놓고 실제 ID는 2개만 넣어서 화면의 숫자와 표가 어긋났다.
CREATE TEMP TABLE tmp_faq (id UUID, subcategory TEXT, question TEXT, answer TEXT,
                           status TEXT, prev_question TEXT, prev_answer TEXT) ON COMMIT DROP;
INSERT INTO tmp_faq VALUES
    (gen_random_uuid(), '바우처 사용 방법', '바우처 잔여 시간은 다음 달로 이월되나요?',
     '월별로 생성된 바우처는 해당 월에 사용하는 것이 원칙이며, 남은 시간은 다음 달로 이월되지 않습니다. 월별 이용 계획을 미리 확인해 주세요.',
     'DRAFT', NULL, NULL),
    (gen_random_uuid(), '결제방법 및 오류', '카드 결제가 잔액 부족으로 실패하면 어떻게 하나요?',
     '급여 잔량과 결제 가능 시간을 먼저 확인한 뒤 단말기에서 재시도해 주세요. 계속 실패하면 단말기 연결 상태를 확인하고 고객센터로 문의해 주시기 바랍니다.',
     'DRAFT', NULL, NULL),
    (gen_random_uuid(), '자격변경', '활동지원 등급이 변경되면 언제부터 적용되나요?',
     '결정 통지서에 기재된 적용 시작일을 기준으로 변경된 급여량이 반영됩니다.',
     'DRAFT', NULL, NULL),
    (gen_random_uuid(), '제공기관운영', '제공기관 정보가 변경되면 어디에 신고해야 하나요?',
     '변경일로부터 7일 이내에 관할 지자체에 변경 신고서를 제출해야 합니다.',
     'DRAFT', NULL, NULL),
    -- 개정 이력(FAQ 검수 화면의 `이력`)을 보여주기 위한 게시본 1건.
    (gen_random_uuid(), '결제내역', '이용 내역과 잔여량은 어디서 확인하나요?',
     '홈페이지 월별 조회 메뉴에서 지난 달 기준으로도 이용 내역과 잔여량을 확인하실 수 있습니다.',
     'PUBLISHED', '남은 바우처는 어디서 확인하나요?', '홈페이지에서 확인할 수 있습니다.'),
    -- 반려 예시 1건.
    (gen_random_uuid(), '본인부담금입금', '본인부담금을 현금으로 납부해도 되나요?',
     '답변 근거가 확인되지 않아 반려한 초안입니다.',
     'DISCARDED', NULL, NULL);

INSERT INTO faq_entries (id, subcategory, question, answer, source_call_count, sample_call_ids,
                         status, generated_at, published_at, updated_at, reviewed_by_counselor_id)
SELECT f.id, f.subcategory, f.question, f.answer,
       COALESCE(jsonb_array_length(s.ids), 0), COALESCE(s.ids, '[]'::jsonb),
       f.status,
       CURRENT_DATE + INTERVAL '6 hours',
       CASE WHEN f.status = 'PUBLISHED' THEN CURRENT_DATE + INTERVAL '8 hours' END,
       CURRENT_DATE + INTERVAL '8 hours',
       CASE WHEN f.status <> 'DRAFT' THEN (SELECT id FROM counselors WHERE login_id = 'admin') END
FROM tmp_faq f
CROSS JOIN LATERAL (
    -- 같은 소분류의 실제 콜을 근거로 붙인다. 없으면 아무거나 3건.
    SELECT jsonb_agg(x.id) AS ids
    FROM (SELECT t.id FROM tmp_call_final t WHERE t.subcategory = f.subcategory ORDER BY t.n LIMIT 6) x
) s;

-- 게시된 항목 중 이전 문안이 있는 건은 개정 이력을 남긴다(FAQ 검수 화면의 "이력" 확인용).
INSERT INTO faq_entry_revisions (id, faq_entry_id, question, answer, revised_by_counselor_id, revised_at)
SELECT gen_random_uuid(), f.id, f.prev_question, f.prev_answer,
       (SELECT id FROM counselors WHERE login_id = 'admin'),
       CURRENT_DATE + INTERVAL '7 hours'
FROM tmp_faq f
WHERE f.prev_question IS NOT NULL
  AND EXISTS (SELECT 1 FROM counselors WHERE login_id = 'admin');

COMMIT;

-- ── 8b. 기존 FAQ (장애인 활동지원제도 100문 100답) ─────────
-- AI-model/data/processed/faq_docs.jsonl에서 뽑은 공식 문서 기반 문답 100건.
-- 이미 확정된 안내문이라 전부 PUBLISHED로 넣는다 — FAQ 검수 화면의 `게시됨` 탭이 이걸로 채워지고,
-- 초안을 검수할 때 `관련 기존 FAQ`(같은 소분류 비교)가 실제로 걸리는 것도 이 100건 덕분이다.
-- 소분류는 질문/답변 문구를 키워드로 분류해 붙였다(중분류-소분류 짝은 항상 유효한 조합).
-- PDF에서 뽑은 원문이라 목차 머리표('PART 3 …')와 자간을 벌려 조판한 구간('바 우 처 를')이
-- 섞여 있어서 넣기 전에 정규화했다.
-- 콜에서 뽑은 게 아니라 문서에서 온 것이므로 근거 콜은 없다(source_call_count 0).
INSERT INTO faq_entries (id, subcategory, question, answer, source_call_count, sample_call_ids,
                         status, generated_at, published_at, updated_at, reviewed_by_counselor_id)
SELECT gen_random_uuid(), v.subcategory, v.question, v.answer, 0, '[]'::jsonb,
       'PUBLISHED',
       CURRENT_DATE - INTERVAL '30 days',
       CURRENT_DATE - INTERVAL '30 days',
       CURRENT_DATE - INTERVAL '30 days',
       (SELECT id FROM counselors WHERE login_id = 'admin')
FROM (VALUES
    ('신청기준및절차', '장애인 활동지원제도란 무엇인가요?', '신체적·정신적 장애 등의 사유로 혼자서 일상생활과 사회생활을 하기 어려운 장애인에게 급여(서비스)를 제공하여 장애인의 자립생활을 지원하고 그 가족의 돌봄부담을 줄임으로써 장애인의 삶의 질을 높이는 것을 목적으로 하는 제도임 장애인의 자립생활을 지원하고 그 가족의 돌봄부담을 경감하고자 ｢장애인복지법｣에 의거 2007년 4월 활동보조서비스가 최초 시행되었으며, 2009년 7월부터 2011년 3월까지 시범사업을 거쳐 ｢장애인활동 지원에 관한 법률｣ 제정으로 2011년 10월 5일 본 제도가 시행되었습니다.'),
    ('신청기준및절차', '장애인 활동지원은 누가 신청할 수 있나요?', '만 6세 이상~만 65세 미만의 장애인이면 누구나 신청 가능 신청일 기준 만 6세 이상~만 65세 미만의 ｢장애인복지법｣ 상 등록 장애인이면 소득수준과 무관하게 신청 가능하며, 만 6세는 생일이 속하는 달의 전달부터 사전 신청이 가능합니다. 활동 지원서비스는 생일이 속하는 달의 익월 1일부터 이용이 가능하며, 활동지원급여 수급자로 선정 후 65세 도래 시 해당 월의 다음 달까지 서비스를 이용할 수 있습니다. 단, 활동지원급여 수급자였다가 만 65세 이후 장기요양급여를 신청하여 등급외 판정을 받은 경우에는 예외적으로 활동지원급여 신청이 가능합니다.'),
    ('신청기준및절차', '신청장소와 구비서류는 어떻게 되나요?', '주민등록상 주소지 주민센터에 신청하며, 신청에 필요한 서식 작성 후 필수 구비서류와 함께 제출 신청 대상 장애인의 주민등록상 주소지 읍·면·동(주민센터)에 방문, 우편, 팩스로 신청 가능 합니다. 복지로 사이트(www.bokjiro.go.kr)에서 온라인 신청도 가능하며, 온라인 신청 시 추가 제출서류 첨부가 불가할 경우 읍·면·동에 별도로 제출하여야 합니다. 기본 제출서류로는 주민센터에 구비되어 있는 사회보장급여 신청서 및 바우처카드 발급 신청서, 건강보험증 사본, 본인 명의 계좌 사본이 있으며, 신청 대상자별로 추가 제출서류가 있을 수 있습니다. 추가 제출 서류의 경우 관할 주민센터나 국민연금공단 지사로 신청 전 유선으로 문의하시면 안내받으실 수 있습니다. ※ 추가제출서류: 장애 정도 심사용 진단서, 장애유형별 소견서, 임상심리평가보고서, 4대 사회보험 가입내역, 재학증명서, 수업료 납부증명서, 가족관계증명서 등'),
    ('신청기준및절차', '신청할 수 없는 대상은 누구인가요?', '보장시설 입소, 60일 초과 입원, 교정시설 또는 치료감호시설 수용, 유사 서비스 수급자 등에 해당하는 사람은 신청할 수 없음 장애인 활동지원서비스를 신청할 수 없는 대상은 아래와 같습니다. 1) ｢노인장기요양보험법｣ 제2조제1호에 따른 노인 등에 해당하는 사람 2) ｢국민기초생활보장법｣ 제32조에 따른 보장시설에 입소한 사람 3) ｢의료법｣ 제3조에 따른 의료기관에 60일을 초과하여 입원 중인 사람 4) 형의 집행 및 수용자의 처우에 관한 법률 또는 치료감호 등에 관한 법률에 따른 교정시설 또는 치료감호시설에 수용 중인 사람 5) 그 밖에 다른 법령에 따라 활동지원급여와 비슷한 급여를 받고 있는 사람 또는 수급자격이 있는 사람 6) ｢장애인복지법｣ 제32조의2에 따라 장애 등록한 재외동포 및 외국인 7) ｢장애인복지법 시행령｣ 제13조제1항 및 제2항에 따른 국가유공자 및 보훈대상자'),
    ('가산단가', '의료기관 입원자의 경우 60일 초과 여부 확인을 위한 입원기간 계산은 어떻게 하나요?', '1회의 입원기간을 산정하며, 반복적 입원진료는 가산하나 특별한 사정이 있는 경우는 가산하지 않음 일반적으로 질병치료를 위한 1회의 입원기간을 의미하나, 간헐적·반복적으로 입원진료를 받은 경우에는 전·후의 입원기간을 가산합니다. 입원기간을 가산하는 경우 그 범위는 당해 연도 1월 1일부터 12월 31일로 합니다. 단, 퇴원 후 질병의 악화·재발 또는 다른 질병에 의한 입원 등 특별한 사정이 있는 것으로 확인되는 경우에는 전·후의 입원기간을 가산하지 않을 수 있습니다.'),
    ('바우처생성', '산재 간병급여 수급자도 활동지원서비스 신청이 가능한가요?', '산재 간병급여 수급자도 활동지원서비스 신청 가능 활동지원급여 신청이 가능합니다. 다만, 근로복지공단에서는 간병급여에서 활동지원급여 월 한도액에 해당하는 금액을 차감하여 지급합니다.'),
    ('사업운영 및 기존정보', '신청자는 모두 활동지원서비스를 이용할 수 있나요?', '국민연금공단의 종합조사 및 지자체 심의 등을 통해 활동지원급여 수급자격 결정 후 서비스 이용 가능 신청절차가 완료되면 지자체에서 국민연금공단으로 조사를 의뢰하며, 공단은 수급자격 여부 및 급여량(시간) 산정을 위해 신청자를 방문하여 대면조사를 실시합니다. 조사 후 지자체 수급 자격심의위원회 심의를 거쳐 최종적으로 급여 지급이 적합하다고 판정된 경우에 서비스를 이용할 수 있으며, 판정결과 확인은 신청일로부터 약 한 달 정도 소요됩니다.'),
    ('자격변경', '종합조사 및 판정 기준은 어떻게 되나요?', '서비스지원 종합조사표에 따라 면담·관찰 등으로 종합조사가 실시되며, 조사 내용을 토대로 수급자격심의위원회에서 최종 결정 종합조사란, 신청자분의 활동지원 급여 수급자격 결정과 급여량(시간)을 산정하기 위한 신체· 정신 기능 제한 정도, 사회활동·가구환경 및 서비스 욕구 조사를 의미합니다. 신청자분과의 면담과 관찰을 통해 진행되며, 성인은 36개 항목, 19세 미만 아동은 27개 항목을 조사하게 됩니다. 장애유형과 신청자 특성을 고려하여 각 항목별 점수가 계산되며, 총 합산된 점수로 급여(시간)가 산정됩니다. 조사 후 학계, 의료인, 장애인복지 전문가, 공무원 등으로 구성된 수급자격심의위원회에서 조사내용과 신청자의 종합적인 상태를 심의해 최종적으로 수급자격이 결정됩니다.'),
    ('자격변경', '종합조사 결과에 대해 이의신청을 할 수 있나요?', '종합조사 결과 통지를 받은 후 90일 이내에 1회에 한하여 신청 가능 가능합니다. 결과를 통지받은 날로부터 90일 이내에 1회에 한하여 신청하실 수 있습니다. 이의 신청은 주민센터에 구비된 이의신청서를 작성 후 제출하시면 되며, 국민연금공단에서 1차 조사원 외 다른 조사원이 신청자를 방문하여 종합조사를 다시 실시하게 됩니다. 조사 이후 60일 이내에 이의신청 결과를 통보받으실 수 있습니다. 장애인 활동지원서비스'),
    ('자격 및 교육', '내용 및 범위 PART 2 활동지원서비스는 어떻게 이용할 수 있나요?', '주소지 인근 활동지원서비스 제공기관과 계약을 통해 서비스를 제공하는 활동지원사를 매칭 받아 서비스 이용 지자체에서 발송한 사회보장급여 결정통지서에 함께 동봉된 주소지 인근 활동지원서비스 제공 기관 정보를 참고하시어 활동지원기관과 직접 계약 및 활동지원사를 매칭 받아 서비스를 이용 하실 수 있습니다. 활동지원기관 정보는 장애인활동지원 홈페이지(www.ableservice.or.kr) 에서도 확인 가능합니다.'),
    ('자격 및 교육', '어떤종류의서비스를이용할수있나요?', '신체활동, 가사활동, 사회활동 등에 대한 서비스를 이용할 수 있음 활동지원급여는 현금이 아닌 바우처 서비스 형태로 이용이 가능하며, 활동지원기관을 통해 매칭 받은 활동지원사에게 아래와 같은 일상생활 지원을 받을 수 있습니다. 구분 세부내용 신체활동지원 개인위생관리 목욕 도움(목욕 준비, 몸씻기 보조 등), 구강 관리 (양치질 도움, 틀니 손질 등), 세면 도움(세면 준비, 세면 보조 등), 배설 관리(배뇨 도움, 화장실 이동보조 등), 옷 갈아입기(의복 준비, 속옷 갈아입기 등) 신체기능 유지 증진 체위 변경(체위 변경 도움, 일어나 앉기 도움 등), 신체기능의 증진(관절구축 예방 활동, 기구사용 운동 보조 등) 식사 도움 식사 차리기, 식사 보조, 구토물 정리 등 실내이동 도움 실내에서 휠체어로 옮겨 타기, 집안 내 걷기 도움 등 가사활동지원 청소 및 주변정돈 수급자가 주로 거주하는 청소(방, 거실) 및 화장실 청소, 쓰레기 분리수거, 내부정리, 이부자리 정돈, 화장대·책장 정리, 옷장·서랍장 정리 등 세탁 수급자의 옷, 양말, 수건, 침구류, 걸레 등의 세탁 및 삶기 등 취사 식재료 준비, 밥 짓기, 국·반찬 하기, 식탁 청소, 설거지, 행주 삶기, 음식물 쓰레기 분리수거 등 사회활동지원 등하교 및 출퇴근 지원 출·퇴근 및 등·하교 보조(부축, 동행), 직장이나 학교 등에서 식사 및 화장실 이용 보조 등 외출시 동행 산책, 물품 구매, 종교활동, 복지시설 이용, 은행, 관공서, 병원 등 방문 및 귀가 시 부축 또는 동행 등 그 밖의 제공서비스 수급자 자녀의 양육 보조(6세 이하 자녀 등 예외적인 경우에 한하며, 반드시 자녀 1인 만을 대상으로 서비스를 제공하여야 함), 생활상의 문제 상담 및 의사소통 도움, 수급자 또는 그 배우자의 출산 후 6개월 기간 내에 수급자의 가족에게 서비스 가능'),
    ('자격변경', '활동지원서비스를 받을 수 있는 기간이 정해져 있나요?', '3년의 유효기간이 부여되며, 유효기간 종료 전 반드시 갱신신청을 해야 유효기간 연장 및 서비스 이용이 가능 활동지원서비스 유효기간은 3년입니다. 유효기간은 결정통지서에 기재되어 있는 급여개시일이 속한 달의 다음달 1일부터 산정됩니다. 유효기간 종료 후에는 서비스를 받으실 수 없으며, 유효 기간 종료일 90일 전부터 30일 전까지 주민센터에 반드시 갱신신청을 하셔야 합니다. 갱신 신청 후, 국민연금공단의 종합조사를 통해 급여(시간)를 다시 산정받게 됩니다.'),
    ('본인부담금입금', '활동지원서비스 이용자가 부담해야 하는 금액이 있나요?', '매월 일정액의 본인부담금 납부 후 바우처 사용 가능 매월 부담하셔야 하는 본인부담금이 있습니다. 활동지원 수급자는 급여 비용의 일부를 본인 및 부양의무자의 소득·재산 등 생활수준에 따라 차등 부담해야 합니다. 이는 서비스 이용량에 따른 합리적인 차등 부과, 수익자 부담원칙 등을 고려하여 도입되었습니다. 단, 「국민기초생 활보장법」제7조제1항제1호에 따른 생계급여 수급자 또는 제7조제1항제3호에 따른 의료급여 수급자는 본인부담금이 면제됩니다. 【본인부담금 산정 기준(2022년 사업안내 기준)】 (단위: 원) 구분 본임부담률 8구간 7구간 6구간 5구간 4구간 3구간 2구간 1구간 생계·의료급여 수급자 면제 없음 차상위계층 정액 20,000 20,000 20,000 20,000 20,000 20,000 20,000 20,000 기준 중위 소득 70% 이하 4% 159,800 177,600 177,700 177,700 177,700 177,700 177,700 177,700 120% 이하 6% 177,700 177,700 177,700 177,700 177,700 177,700 177,700 177,700 180% 이하 8% 177,700 177,700 177,700 177,700 177,700 177,700 177,700 177,700 180% 초과 10% 177,700 177,700 177,700 177,700 177,700 177,700 177,700 177,700 구분 본인부담률 특례 15구간 14구간 13구간 12구간 11구간 10구간 9구간 생계·의료급여 수급자 면제 없음 차상위계층 정액 20,000 20,000 20,000 20,000 20,000 20,000 20,000 20,000 기준 중위 소득 70% 이하 4% 27,800 35,500 53,300 71,000 88,800 106,600 124,300 142,100 120% 이하 6% 41,800 53,300 79,900 106,600 133,200 159,900 177,700 177,700 180% 이하 8% 55,700 71,100 106,600 142,100 177,600 177,700 177,700 177,700 180% 초과 10% 69,700 88,900 133,300 177,700 177,700 177,700 177,700 177,700 【본인부담금 결정 및 변경】 - 관할 시·군·구에서 매년 5월 1일부터 본인부담금을 새로 산정하여 5월 27일에 결정하며, 결정 내역은 당해연도 6월부터 다음연도 5월까지 적용됩니다. - 기초생활보장급여 수급권 취득 및 상실, 차상위계층 또는 의료급여 수급권 취득 및 상실, 월별 건강보험료액 변경, 가구원수 변경 등의 사유가 있는 경우 본인부담금 변경이 가능하며, 주민센터에 신청하시면 됩니다.'),
    ('본인부담금입금', '본인부담금을 지자체 예산으로 지원받을 수 있나요?', '본인부담금은 지자체 예산으로 지원받을 수 없음 수급자의 수익자 부담 원칙 등 본인부담금 부과 취지를 고려할 때 지자체 예산으로 본인부담금을 지원하는 것은 불가합니다.'),
    ('본인부담금환급', '활동지원급여를 전부 소진하지 못했는데 본인부담금은 어떻게 되나요?', '활동지원급여 미소진시, 본인부담금 이월 또는 환급 가능 지자체는 납부된 본인부담금 중 수급자가 활동지원급여를 이용하지 않아 지급되지 않은 본인 부담금을 정산하여 환급하거나 다음 연도로 이월할 수 있습니다. 활동지원서비스가 해지된 경우에는 별도로 신청하지 않더라도 한국사회보장정보원이 이용자의 환급계좌로 본인부담금 잔액을 환급하며, 사업연도 종료 시 본인부담금 잔액이 발생한 경우 이를 이용자의 다음연도 본인부담금으로 활용합니다.'),
    ('자격 및 교육', '활동지원서비스 이용자가 부재중일 때 활동지원사가 집안일 등 가사서비스를 제공할 수 있나요?', '이용자 부재 시 제공한 서비스는 적정한 서비스로 보기 어려우며, 불가피한 사정이 확인되는 경우만 예외적으로 인정 활동지원사가 당해 방문시간 동안 이용자 본인을 위한 신체·가사활동 지원 등 서비스를 제공 하면 이용자는 서비스 전·후 내용을 확인하여 바우처 카드로 실시간 결제하는 것이 원칙입니다. 따라서 이용자가 집을 비운 동안 활동지원사 혼자 가사활동지원 등을 제공하였다면 이는 급여 비용 청구 대상이 될 수 없습니다. 다만, 이용자와 떨어져서 서비스를 제공해야만 하는 불가피한 사정이 확인된다면 예외적으로 인정될 수 있으며, 이러한 예외적인 인정 여부는 지자체에서 이용자의 상황을 종합적으로 고려하여 판단합니다.'),
    ('자격 및 교육', '활동지원사가 업무 중 자기 차량을 이용하다가 사고가 발생한 경우 보상 가능한가요?', '활동지원사는 활동지원서비스 이용자에 대해 차량을 지원할 의무가 없으며, 업무 중 자기 차량을 이용하여 사고가 발생한 경우 차량파손에 대한 보상이 어려움 이동보조 서비스는 이용자가 어느 장소에서 다른 장소로 이동할 수 있도록 보조하는 것이지 자동차 등 물적수단을 동원하는 것은 포함되지 않습니다. 또한 활동지원서비스 단가에도 물적 수단 동원에 대한 대가가 포함되어 있지 않으므로 장애인 콜택시 등을 이용하는 것이 바람직합 니다. 부득이 활동지원사의 차량을 이용하여 서비스를 제공하는 경우에는 이용자 또는 보호자, 활동지원사, 활동지원기관이 협의하여 차량 이용 중 발생할 수 있는 사고에 대한 보험가입 등의 대비체계가 마련되어야 합니다. 또한, 장애인의 차량을 활동지원사가 운전하여 서비스를 제공하는 경우 보험관계 등에 비추어 활동지원사가 장애인 차량을 운전할 수 있어야 하고, 활동지원사가 운전하는 중 사고가 발생하는 경우 1차적으로 자동차 소유주가 책임을 부담하므로 사고 발생 시 책임 및 손해배상에 대한 협의가 선행되어야 합니다.'),
    ('제공인력 정보', '활동지원서비스 제공 중 사고가 발생되었을 경우, 활동 지원사의 배상책임 및 부담금 규정은 어떻게 되나요?', '서비스 제공 중에 발생한 사고는 활동지원기관이 가입한 배상책임보험 등을 통해 보상 가능 4대 사회보험 중 산재보험 의무가입과는 별개로, 배상책임보험은 활동지원기관에서 소속 활동 지원사에 대해 의무적으로 가입해야 하며 비용은 활동지원기관이 전액 부담합니다. 또한 산재 보험 미가입 시에는 상해보험을 추가로 가입해야 합니다.'),
    ('신청기준및절차', '보장시설에서 생활하는 경우, 서비스를 제공받을 수 없나요?', '국민기초생활 보장법에 따른 보장시설 입소자는 활동지원서비스 신청 자체가 불가. 단, 장애인단기거주시설 이용자는 신청 가능하며 이 경우 시설 내 이용은 불가 그렇습니다. ｢국민기초생활 보장법｣ 제32조에 따른 보장시설에 입소한 사람은 활동지원 신청 자격이 없습니다. 다만, 장애인공동생활가정(그룹홈)과 장애인단기거주시설에서 생활하시는 경우에는 신청이 가능합니다. 신청 후 수급자격을 인정 받아 서비스를 이용하는 경우, 해당 시설 내에서 서비스 이용은 불가하며 시설 밖에서 이용한다는 시설장의 확인서 등 증빙이 필요 합니다.'),
    ('신청기준및절차', '직장에서 근로하고 있는 이용자가 직장 내에서 활동지원서비스를 받을 수 있나요?', '근로지원서비스 우선 이용이 원칙임 직장에서 근로하는 중엔 원칙적으로 활동지원서비스를 제공 받을 수 없습니다. 직장 내에서는 장애인고용공단에서 운영하는 근로지원서비스를 통해 근로지원인 또는 직무보조인을 활용해야 합니다. 참고로, 활동지원사는 활동지원서비스 이용자 또는 그 가족의 사업장·직장 등에서 업무를 보조하는 등 생업을 지원하는 행위는 금지되어 있습니다.'),
    ('신청기준및절차', '직장 내에서 근로지원인의 도움을 받을 수 없는 경우 , 활동지원서비스 이용이 가능한가요?', '근로지원인 서비스를 받을 수 없는 경우에는 활동지원서비스 이용 가능 직장 내에서는 근로지원인 서비스가 우선 이용되어야 하나, 근로지원인 신청 대상이 아니거나 서비스 신청 후 예산부족 사유로 탈락하는 등 근로지원인 서비스를 받을 수 없는 경우에는 활동지원서비스 이용이 가능합니다. 또한 신변처리 등을 근로지원인에게 지원받을 수 없는 경우나 서비스 시간 부족으로 근로지원인 서비스를 지원받을 수 없는 경우에 한하여 제한적으로 활동지원서비스 이용이 가능하며, 후자의 경우 구체적인 서비스 내용 또는 범위에 따라 이용 가능 여부가 달라질 수 있습니다.'),
    ('자격 및 교육', '활동지원사와 이용자가 1박 2일 여행 시 수면시간이 서비스 제공시간에 포함되나요?', '이용자·활동지원사의 수면시간은 원칙적으로 서비스 이용·제공으로 보기 어려워 서비스 제공시간에 포함 불가 이용자의 수면시간 및 이용자와 활동지원사의 동반 수면시간은 서비스 제공시간이 아닌 대기 시간이며, 대기시간에 대해서는 활동지원서비스 제공시간으로 인정되기 어렵습니다. 다만, 이용자만 수면을 취한 경우 이용자의 장애특성 및활동지원사의 상시 지원 필요여부 등을 종합 적으로 고려하여 실제 서비스가 제공된 시간은 급여비용으로 결제할 수 있습니다.'),
    ('교통비 지급', '이용자가 활동지원사의 이동보조를 받아 대중교통에 탑승하는 경우 활동지원사의 대중교통 요금은 누가 부담해야 하나요?', '이동보조를 위해 발생하는 활동지원사 교통운임은 활동지원 이용자가 부담함 활동지원서비스 이용 중 부가적으로 발생되는 비용(교통비, 입장료, 생필품 구매 등)은 활동 지원 이용자가 부담합니다.'),
    ('자격 및 교육', '활동지원사가 이용자에게 석션 등 의료행위를 제공할 수 있나요?', '활동지원사는 의료와 관련된 서비스를 제공할 수 없음 의료인이 아니면 누구든지 의료행위를 할 수 없으며, 의료인도 면허된 것 이외의 의료행위를 할 수 없습니다. 판례에 따르면 의료행위라 함은 의학적 전문지식을 기초로 하는 경험과 기능으로 진찰, 검안, 처방, 투약, 외과적 시술을 시행하는 질병의 예방, 치료행위 및 그 밖에 의료인이 행하지 아니하면 보건위생상 위해가 생길 우려가 있는 행위를 의미합니다. 음식투여나 흡인행위는 그 과정에서 ‘보건위생상 위해가 발생할 우려가 있는 행위’에 포함되므로 의료인이 하여야 할 것이며 활동 지원사, 간병인 및 보호자가 전문성을 갖추지 않은 상태에서 행위를 하는 것은 부적절합니다. 활동지원제도 중 방문간호를 이용하여 석션이 이루어지는 것이 바람직합니다.'),
    ('서비스비용 지급', '2인 이상의 활동지원사가 동일한 이용자에게 동시에 서비스를 제공할 수 있나요?', '급여비용의 산정특례에 따라 활동지원사 2인이 동시에 서비스 제공 가능 수급자의 신체·정신적 상태 또는 목욕 도움 등 급여 내용 상 활동지원사 1인 만으로 급여 제공이 어려운 경우 수급자 등의 신청에 따라 동일 기관의 활동지원사 2인이 급여를 제공할 수 있습니다. 급여비용은 활동지원사별로 각각 산정할 수 있으며, 각 활동지원사의 급여비용은 1회 방문 당 3시간의 범위 내에서 급여비용의 100%로 산정합니다. 이 경우 수급자 등의 동의를 얻고 그 내용을 활동지원급여 제공기록지 등에 기재해야 합니다.'),
    ('가산단가', '활동지원급여 가산수당이란 무엇인가요?', '서비스 이용에 어려움을 겪는 것으로 인정되는 수급자에게 서비스를 제공하는 활동지원사의 급여비용에 대해 추가적인 수당을 지원해주는 제도 급여비용별 가산수당 및 가산수당 대상자 선정은 아래와 같습니다. 【가산수당 금액】 【가산수당 대상자 선정】 ○ 1순위 대상 수급자는 종합조사 결과에 따라 자동으로 선정되, 2순위 대상 수급자는 별도의 심의기구 등을 통해 지자체에서 결정 1) 1순위 대상 수급자: 서비스지원 종합조사 결과 기능제한 영역 합산점수가 성인 446점 이상, 아동 347점 이상인 사람 2) 2순위 대상 수급자: 다음 어느 하나에 해당되고 2개월 이상 활동지원사 연계가 되지 않거나 3개월간 6회 이상 활동지원사가 교체된 수급자 중 예산 등을 고려하여 지자체에서 결정 - 기존 인정점수 440점 이상으로 1순위 대상자였으나 갱신 후 1순위에 미해당 - 발달장애인으로 공격성, 폭력성, 돌발행동 등 행동장애가 심하여 활동보조서비스 제공에 현저한 곤란이 있음 - 와상, 사지마비 및 수급자 특성 등으로 대소변 처리, 목욕, 이동 등 활동보조서비스 제공에 현저한 곤란이 있음 - 기타 이에 준하는 사유가 있다고 시·군·구에서 인정 분류 시간당 금액 ① 매일 일반적으로 제공하는 경우 기본 14,800원 → 가산수당 2,000원 ② 22시 이후 6시 이전 심야에 제공하는 경우 기본 22,200원 → 가산수당 3,000원③ ｢관공서의 공휴일에 관한 규정｣에 의한 공휴일과 근로자의 날에 제공 하는 경우 수급자의 사회활동·가구환경 인정기준'),
    ('신청기준및절차', '생활환경 영역을 인정받기 위해 어떤 서류가 필요하나요?', '구분 구비서류 사회활동 직장생활 ▪4대 사회보험 가입 직장 근로: 4대 사회보험 가입내역 ▪생계·의료급여 수급자로 4대 사회보험 가입대상에서 제외된 사람 : 근로소득원천징수영수증, 근로계약서 사본, 재직증명서 모두 제출 ▪장애인직업재활시설 이용자: 직업재활시설 이용확인서(임의서식) ▪사업소득만 있는 경우: 사업자등록증 사본 및 사업소득 신고내역 ▪농업: 농지원부 또는 농업소득보전직접직불금 자료 ▪임업: 입목재산자료 ▪어업: 어업권 및 선박 보유내역 학교생활 재학 또는 입학예정임을 입증할 수 있는 자료 : 재학증명서, 수업료 납부증명서, 취학통지서, 학교배정통지서 등 가구환경 1인(독거)가구 수급자의 가족관계증명서 취약가구 수급자의 가족관계증명서 한부모 및 조손가족 수급자의 가족관계증명서 또는 한부모가족증명서 본인을 제외한 가족의 사회생활 수급자의 가족관계증명서 및 기타 가족의 장애정도, 직장생활, 학교 생활에 대한 증빙서류'),
    ('대상자정보', '수급자가 근로 중인 사업장이 4대 사회보험에 미가입 되어 있는 경우, 재직증명서만으로 직장생활 인정이 가능한가요?', '4대 사회보험 가입내역을 제출해야 직장생활 인정 가능 근로자의 경우 재직증명서 제출로는 직장생활 인정이 어려우며, 4대 사회보험 가입내역을 제출 해야만 직장생활로 인정 가능합니다. 단, 4대 사회보험 가입대상이 아닌 생계·의료급여 수급 자의 경우 근로소득원천징수영수증(분실 등으로 제출이 어려운 경우 근로소득지급조서), 근로 계약서 사본, 재직증명서를 모두 제출하시면 직장생활 인정이 가능합니다.'),
    ('신청기준및절차', '근로자의 경우 4대 사회보험 종별로 가입내역을 모두 제출해야 하나요?', '건강보험직장·국민연금사업장·고용보험 가입자 가입내역 확인서 중 한 가지만 제출하여도 직장생활 인정 가능 건강보험직장·국민연금사업장·고용보험 중 한가지 가입내역만 제출하여도 직장생활 인정 가능합니다. 다만, 산재보험 가입내역의 경우 상시 종사하는 근로자 여부 판단이 어려워, 다른 종별의 가입내역이 함께 확인되어야 합니다.'),
    ('신청기준및절차', '사업소득 신고내역을 증빙할 수 있는 구체적인 자료는 무엇인가요?', '사업소득 신고내역 증빙자료로는 세금 신고 내역, 소득금액증명원, 부가가치세 과세표준증명원 등이 있음 세금 신고 내역 또는 신고 이후 발급되는 소득금액증명원, 부가가치세 과세표준증명원 등이 있으며, 상시·지속적인 사업운영 여부를 확인하기 위해 가장 최근의 신고내역을 제출하셔야 합니다. 참고로 아래 내용을 확인하시기 바랍니다. 【참고: 종합소득세·부가가치세 신고】 유형 신고 대상자 신고 주기 과세대상 기간 신고 및 납부기간 종합소득세 사업소득이 있는자 연 1회 1.1.~12.31. 다음해 5.1.~5.31. 부가가치세 법인사업자 연 4회 예정신고 1.1.~3.31. 4.1.~4.25. 확정신고 1.1.~6.30. 7.1.~7.25. 예정신고 7.1.~9.30. 10.1~10.25. 확정신고 7.1.~12.31. 다음해 1.1~1.25. 개인 일반사업자 연 2회 1.1.~6.30. 7.1.~7.25. 7.1.~12.31. 다음해 1.1.~1.25. 개인 간이사업자 연 1회 1.1.~12.31. 다음해 1.1.~1.25.'),
    ('대상자정보', '수급자가 안마원을 운영하고 있으나 면세사업자로 부가가치세 신고를 하지 않는 경우, 어떤 증빙자료로 직장생활 인정이 가능한가요?', '사업장현황 신고내역 또는 부가가치세 면세사업자 수입금액증명원으로 직장 생활 인정 가능 부가가치세 신고 제외 대상(면세사업자)은 매년 사업현황 및 수입금액 등을 다음해 1월 1일부터 2월 10일 사이 세무서에 신고하여야 하므로, 사업장현황 신고 내역 또는 신고 이후 발급되는 수입금액증명원 제출로 직장생활 인정이 가능합니다.'),
    ('신청기준및절차', '사업자등록증은 보유하고 있으나 사업소득이 확인되지 않는 경우, 직장생활을 인정할 수 있나요?', '사업자등록증 및 사업소득이 모두 확인되어야 직장생활 인정이 가능하며, 사업 초기라 사업소득이 확인되지 않는 경우 추가 증빙자료 제출로 인정 가능 사업자등록증과 사업소득이 모두 확인되어야 직장생활 인정이 가능합니다. 다만, 사업자등록 초기로 사업소득 신고시기가 도래하지 않아 사업소득이 확인되지 않는 경우에 한하여 실제로 사업 운영을 하고 있음을 입증할 수 있는 서류* 제출 시 예외적으로 인정 가능합니다. * 전자세금계산서, 매출·매입 증빙, 신용카드매출전표, 현금매출명세서, 4대 사회보험'),
    ('대상자정보', '납부증명서 등 장애인단체 등의 무보수대표이사로 일하고 있는 수급자의 경우 직장생활이 인정되나요?', '재직 등을 증빙할 수 있는 서류와 상근 여부가 확인되어야 인정 가능 직장생활은 4대 사회보험 가입내역으로 증빙하는 것이 원칙이나, 무보수 대표이사의 경우에는 단체(협회) 고유번호증(수익사업을 하는 경우 사업자등록증), 무보수 관련 사항이 명시된 이사회 정관, 재직증명서 등과 함께 상근 여부가 확인되면 예외적으로 직장생활 인정이 가능합니다.'),
    ('사업운영 및 기존정보', '대한안마사협회 부설 안마수련원의 수련생인 경우 직장생활이 인정되나요?', '지자체에 장애인직업재활시설로 등록된 안마수련원은 인정 가능 해당 안마수련원이 관할 시장·군수·구청장에게 장애인직업재활시설*로 설치·운영 신고를 하여 장애인복지시설 신고증을 교부받은 경우라면, 이용확인서 제출로 직장생활 인정이 가능 합니다. 장애인직업재활시설로 등록되지 않은 안마수련원은 직장생활이 인정되지 않습니다. * 장애인직업재활시설 유형: 장애인 보호작업장, 장애인 근로사업장, 장애인 직업적응훈련'),
    ('자격 및 교육', '시설 농업 종사자이나 공적자료 조회를 통해 농지소유가 확인이 되지 않는 경우 직장생활로 인정 가능한가요?', '농지를 소유하고 있지 않더라도 실제 농업에 종사하면 직장생활이 인정됨 농업 종사자가 반드시 농지를 소유해야 직장생활이 인정되는 것은 아니며, 농업소득직접지불금 대상 증명, 농업경영체등록 등 공적자료로 농업에 종사함이 확인되면 직장생활 인정이 가능 합니다.'),
    ('신청기준및절차', '보험설계사 등 프리랜서 형태의 근로자가 직장생활을 인정받기 위해 필요한 서류는 무엇인가요?', '사업소득원천징수영수증 또는 사업소득지급명세서, 근로계약서 등 필요 근로소득이 아닌 사업소득으로 신고하는 프리랜서 형태의 근로자인 경우 사업소득원천징수 영수증 또는 사업소득지급명세서로 사업소득이 확인되고, 근로계약서로 신청일 기준 직전 3개월간 월평균 60시간 이상 근로가 확인된 경우에만 직장생활로 인정 가능합니다.'),
    ('신청기준및절차', '종교인의 경우 직장생활이 인정되나요?', '건강보험 직장가입 또는 국민연금 사업장 가입내역이 확인되는 경우 인정 종교인도 4대 사회보험 적용 대상이므로 건강보험 직장 또는 국민연금 사업장 가입내역서 제출로 직장생활을 인정받을 수 있습니다. 단, 4대 사회보험 중 고용·산재보험은 가입대상이 아닙니다. 구분 근로자 해당 여부 및 적용기준 종교인 (성직자) 건강보험 소득신고 형태에 관계없이 근로의 대가로 보수를 받는 경우 직장 가입 대상 국민연금 ▪근로소득으로 신고시: 근로자에 해당되므로 사업장 가입 대상 ▪기타소득으로 신고시: 사용자(종교단체) 부담금 및 근로자(종교인) 기여금 납부를 합의한 경우 사업장 가입 가능'),
    ('신청기준및절차', '고용·산재 가입 비대상 학교 재학 중 휴학, 결석, 방학기간 등은 학교생활로 인정되나요?', '결석 및 방학기간은 학교생활로 인정하나, 휴학은 학교생활로 인정될 수 없음 재학기간 중 발생하는 결석이나 방학은 일시성과 학업의 연장선상이라는 의미에서 학교생활 인정이 가능합니다. 다만, 휴학의 경우는 학업이 중단된 것으로 보아 학교생활로 인정하기 어려우며 복학 후 신청해야 합니다. ※ 휴직인 경우도 위의 기준과 동일하게 직장생활로 인정되지 않음'),
    ('신청기준및절차', '온라인 사이버대학교, 대안학교, 특수학교 전공과도 학교생활로 인정되나요?', '법령에 따른 정규학교인 경우 학교생활로 인정 ｢고등교육법｣ 제2조에 따른 원격대학(방송대학·통신대학·방송통신대학·사이버대학), ｢초· 중등교육법｣ 제2조에 따른 대안학교, ｢장애인 등에 대한 특수교육법｣ 제24조에 따른 특수학교 전공과에 해당하는 경우 모두 학교생활로 인정되며, 법령에 따른 정규학교가 아닌 비인가 사이버 대학, 비인가 대안학교, 평생교육원 등은 학교생활로 인정되지 않습니다.'),
    ('대상자정보', '주민등록상 주소지와 실거주지가 다른 경우, 가구특성 인정이 가능한가요?', '주민등록상 주소지와 실거주지가 다른 경우, 가구특성(독거, 취약가구 등) 인정되지 않음 가구특성 영역은 주민등록상 주소지와 실거주지가 같은 경우에만 인정 가능하며, 다를 경우 주소지 정리(실거주지로의 주민등록 전입)가 필요합니다. 단, 한부모 및 조손가족은 주민등록상 주소지와 실거주지의 동일 여부에 관계없이 공적자료 상 인정기준에 해당되면 가구특성 인정이 가능합니다.'),
    ('대상자정보', '부모와 같이 살고 있으나 주민등록상 세대 분리된 경우, 독거가구로 인정되나요?', '동일 주소지에서 세대 분리한 경우 독거가구로 인정되지 않음 ｢민법｣ 제779조의 가족의 범위에 해당되는 사람이 수급자와 동일 주소지에 세대 분리하여 거주하는 경우에도 주민등록을 같이 하는 것으로 간주하여 독거가구 인정이 불가합니다. 다만, 부모 모두 만 65세 이상 또는 장애의 정도가 심한 장애인이라면 취약가구로 인정 가능합니다.'),
    ('대상자정보', 'IL센터에서 운영하는 체험홈에서 주민등록상 단독세대로 분리하여 가족관계가 아닌 다른 수급자들과 함께 거주하고 있는 수급자의 경우 독거 또는 취약가구로 인정되나요?', '민법에서 규정한 가족의 범위에 속하지 않는 사람은 동거인으로 판단하므로 독거가구로는 인정되나, 취약가구로는 인정되지 않음 가족 또는 가구구성원의 범위 및 그에 따른 부양 또는 보호 의무를 고려하여 혈연관계 없이 동일한 공간에 함께 거주하는 장애인은 가족구성원이 아닌 동거인으로 판단하므로 독거가구로 인정 가능합니다. 또한 동일한 기준으로, 함께 거주하는 장애인이 가족구성원이 아니므로 취약 가구에는 해당되지 않습니다.'),
    ('신청기준및절차', '만 19세 미만 아동 수급자가 독거가구 신청이 가능한가요?', '만 19세 미만 아동 수급자는 독거가구 신청 불가능 독거가구는 만 19세 이상 성인 수급자만 신청이 가능합니다. 아동 수급자가 1인 가구인 경우 한부모 또는 조손가족으로 인정됩니다.'),
    ('대상자정보', '수급자, 65세 이상 부모, 자녀로 구성된 가구인데 자녀가 군 입대를 한 경우 취약가구로 인정되나요?', '현역병으로 군 입대한 경우만 부재자에 해당하여 취약가구로 인정 가능 자녀가 현역병으로 입대한 경우, 사실상 부재중인 가구구성원에 해당되므로 가구구성원 판단 시 제외됩니다. 따라서 수급자와 만 65세 이상 부모로 구성된 가족으로 판단하여 취약가구로 인정이 가능합니다. 만약 자녀가 사회복무(공익근무)요원, 상근예비역, 장교·부사관으로 복무할 경우 부재자에 해당하지 않아 취약가구로 인정 불가합니다.'),
    ('대상자정보', '수급자와 장애정도가 심한 장애인인 배우자(국민연금공단 심사 이력 없음)로 구성되어 있는 경우 취약가구로 인정되나요?', '국민연금공단 심사이력 유무와 관계없이 가구구성원이 장애의 정도가 심한 장애인인 경우 취약가구 인정 가능'),
    ('대상자정보', '수급자가 가족관계증명서상으로 확인이 불가한 만 65세 이상인 생모와 함께 거주하고 있는 경우 취약가구로 인정되나요?', '공적자료로 확인되는 가구구성원이 아니므로 취약가구로 인정 불가 실제 수급자를 낳은 생모라고 하더라도 공적자료로 확인되지 않는 경우 취약가구로 인정되지 않습니다. 다만, 가족관계증명서상 확인이 불가한 생모는 가구구성원이 아니라 동거인으로 간주되므로 독거가구로는 인정이 가능합니다.'),
    ('가산단가', '본인을 제외한 가족의 사회생활 인정기준에서 최중증 수급자란 누구를 의미하나요?', '서비스지원 종합조사 결과, 기능제한(X1) 영역의 합산점수가 성인의 경우 360점 이상, 아동의 경우 280점 이상인 수급자가 최중증 수급자에 해당'),
    ('신청기준및절차', '수급자가, 가구구성원의 직장 입사로 본인을 제외한 가족의 사회생활을 인정받고자 하는 경우 변경신청이 가능한가요?', '가구구성원이 본인을 제외한 가족의 사회생활 인정기준에 해당하면 변경신청 가능 ’19.6.30. 이전 인정조사로 결정된 수급자의 경우 가구구성원이 인정기준(19세 미만 또는 65세 이상, 장애정도가 심한 장애인, 학교재학, 직장재직 중 해당)에 해당하면 최중증 수급자 여부에 관계없이 본인을 제외한 가족의 사회생활 신청이 가능하며, 공적자료·증빙서류 등으로 가구 구성원의 인정기준 확인이 불가한 경우 신청할 수 없습니다. 최중증 수급자가 사업자등록증을 보유중이며 배우자는'),
    ('대상자정보', '수급자의 가게에서 일을 하고 있지만 별도의 소득은 없는 경우, 배우자가 본인을 제외한 가족의 사회생활로 인정되나요?', '배우자의 근로소득이 공적자료로 확인되지 않으면 본인을 제외한 가족의 사회 생활로 인정되지 않음 배우자의 직장생활을 증빙할 수 있는 공적자료가 없는 경우 직장생활로 인정할 수 없으며 이에 따라 본인을 제외한 가족의 사회생활에도 해당되지 않습니다. 다만, 배우자와 공동명의로 사업 자등록을 하고, 배우자 명의로 사업소득이 신고된 내역이 확인되는 경우 인정이 가능합니다.'),
    ('대상자정보', '최중증 수급자가 평생교육시설에 다니고 있는 아들과 거주하는 경우, 본인을 제외한 가족의 사회생활로 인정이 가능한가요?', '수급자의 아들이 법령에 따른 평생교육시설에 다니는 경우 인정 가능 법령에 따른 평생교육시설이란 ｢평생교육법｣ 제20조2에 따른 장애인평생교육시설, ｢평생교육법｣ 제31조에 따른 학교형태의 평생 교육시설을 의미합니다.'),
    ('대상자정보', '최중증 수급자의 아들이 사회복무요원으로 복무하는 경우, 본인을 제외한 가족의 사회생활로 인정되나요?', '본인을 제외한 가족의 사회생활 인정 가능. 현역병이 아닌 사회복무요원 또는 상근예비역인 경우, 가구구성원 판단 대상에 포함되며 직장생활을 하는 것으로 인정됩니다.'),
    ('신청기준및절차', '한부모가족증명서 발급이 안되는 대상은 한부모 및 조손가족으로 인정이 안되나요?', '수급자 기준의 가족관계증명서로 인정 받을 수 있으며, 가족관계증명서로 확인이 안되는 경우 증빙서류 추가 필요 수급자 기준의 가족관계증명서로 ｢한부모가족지원법｣ 제4조제1호 또는 제5조의2제2항에 해당함을 확인할 수 없는 경우 관련 사실의 증빙서류*를 추가로 제출해야 한부모 및 조손가족 으로 인정됩니다. * 부모 또는 부모 중 1인의 부재함을 입증할 수 있는 서류(부 또는 모의 혼인관계증명서, 수용증명서, 실종 등의 신고접수서, 병적증명서 등 ※ 지자체 담당자가 전산(사회보장정보시스템)을 통해 부모 또는 부모 중 1인의 부재여부를 확인한 경우 전산화면 캡처본 등 전산에서 확인했음을 증빙할 수 있는 자료의 제출로 한부모 및 조손가족 증빙서류 대체 가능'),
    ('신청기준및절차', '한부모 및 조손가족 인정을 받기 위해 별도의 소득 기준을 충족해야 하나요?', '장애인 활동지원제도에서의 한부모 및 조손가족 인정 시 별도 소득기준 없음 활동지원제도의 한부모 및 조손가족 인정 여부는 소득 수준으로 판단되지 않습니다. 다만, 한부모가족지원법에 따른 지원대상에 선정되기 위해서는 해당 사업지침에 따른 소득기준을 충족해야 합니다.'),
    ('가산단가', '수급자의 주민등록상 주소지는 2층 이상의 아파트로 되어 있으나, 현장조사 결과 단독주택 1층에 거주하는 경우 주거특성 점수가 인정되나요?', '실제 거주지 위치를 반영하기 때문에 인정되지 않음 실제 지하층 또는 2층 이상에 거주하지 않는 것으로 확인되는 경우 주거특성에서 점수 인정이 불가합니다. 주민등록상 주소지와 실거주지가 다르나 실제 거주지에서 지하층 또는 2층 이상에 거주하는 것으로 확인되면 주거특성 인정이 가능하며, 이 경우에도 주민등록상 주소지가 지하층 또는 2층 이상인 경우에 한하여 인정됩니다. 장애인 활동지원기관 및 활동지원사 교육기관 PART 4'),
    ('제공기관운영', '장애인 활동지원서비스 제공기관 지정절차는 어떻게 되나요?', '‘지자체 공모 계획 수립·공고 → 신청접수 → 현지확인 → 심사위원회 개최 → 선정 및 지정 → 전산입력 → 활동지원기관 지정서 발송 → 공단 등 통보’의 절차를 통해 활동지원기관으로 지정됩니다. 활동지원기관으로 지정받고자 신청하는 경우에는 반드시 아래의 시설 및 인력기준을 갖춘 후 신청해야 합니다. 구분 분류 충족 기준 시설 기준 시설 규모 전용면적에 대한 별도 기준은 없으나 장애인과 그 가족에 대한 상담· 교육, 활동지원사 교육 및 관리업무 등에 필요한 전용공간을 반드시 갖춰야 함 시설 위치 활동보조에 대한 수요, 활동지원기관 분포의 적정성, 교통편의 등을 고려하여 장애인이 쉽게 접근할 수 있는 곳에 위치 사무실 통신설비, 집기 등 사업에 필요한 설비 및 비품을 갖춰야 함 상담실 장애인과 그 가족 등을 위한 상담 및 교육에 필요한 공간으로, 상담용 탁자 및 의자 등을 갖춰야 함 활동지원사 교육장 소속 활동지원사 15명(농어촌 지역 5명) 이상 참석 가능한 면적 이어야 하며, 사무실과 별도의 장소에 교육장소를 두는 경우에는 이를 입증할 수 있는 서류(사용계약서, 등기부등본, 임대차계약서)를 함께 제출해야 함 인력 기준 관리책임자 1명 전담관리인력 1명 이상 활동지원사 15명 이상(농어촌 지역 5명 이상) ※ (신규 지정기관 특례) 최초로 활동지원기관을 지정하는 경우 지정한 때부터 6개월 범위에서 활동지원사 수는 완화된 기준 (농어촌 3명, 그 외 10명) 적용 가능하며, 특례 기간이 지난 후 에는 인력기준에 맞지 않을 경우 지정 취소 지자체는 ｢장애인활동지원기관 등의 지정에 관한 고시｣에서 정한 심사기준에 따라 심사하며, 심사결과 80점 이상, 고득점 순으로 지정기관을 선정합니다. 구분 심사항목 배점 기관현황 사회복지법인 등 설치 기관(법인)의 공익성 10 기관의 관할 지역내 접근성, 지역적 분포 4 활동보조 이외의 사회복지사업 실적 5 최근 3년간 활동보조급여 제공 실적 5 사무실, 교육실 등 시설 설치 현황 3 급여제공 능력 활동지원사 수 10 전담인력 수 10 차량 및 기타 관련 장비 운용 현황 3 급여관리 계획 활동지원사 및 수급자 등에 대한 교육 계획 및 실적 5 예산 조달방안 등 사업운영계획의 타당성 5 위험관리체계 구축 및 타당성 5 자체 사업평가 계획의 타당성 5 인력관리 활동지원사 중 상근인력 비율 5 활동지원사의 임금 수준 5 활동지원사의 사회보험, 상해보험 및 배상책임보험 가입 비율 5 신규 활동지원사 확보방안의 타당성 5 기타 지자체별 자체평가 기준 10 합계 100 감점 행정지도 및 민원 5'),
    ('자격 및 교육', '활동지원기관장, 관리책임자 등 기관 종사자의 정년이 별도로 정해져 있나요?', '활동지원기관 종사자에 대한 별도 정년기준 없음 사회복지시설 시설장 및 종사자에 대한 정년제는 의무가 아닌 권고사항이며, 정년제는 종사자의 신분을 보장하기 위한 제도가 아니라 정부의 인건비 보조금 지급 연령 상한기준(시설장 만 65세, 종사자 만 60세) 입니다. 참고로, 활동지원기관은 사회복지시설로 분류되지는 않으나 사회복지시설 관련 법·규정을 준용하고 있습니다. (보건복지부 ｢2022년 사회복지시설 관리 안내｣ 참조)'),
    ('제공인력 정보', '활동지원기관에서 전담관리인력으로 근무하다가 사회복지시설로 이직하는 경우, 종전 전담관리인력 근무 경력은 사회복지시설 경력(호봉) 산정 시 인정받을 수 있나있나요?', '종전 활동지원기관 전담관리인력으로 근무한 경력의 80%를 인정 보건복지부 ｢2022년 사회복지시설 관리안내｣ 참조'),
    ('자격 및 교육', '하나의 활동지원기관에서 여러 곳의 사무실 운영이 가능한가요?', '권리의무 주체가 동일한 경우 사업의 원활한 수행을 위해 여러 개의 사무실 운영 가능 활동지원기관 지정 당시 시설 기준 이외의 장소에 별도의 사무공간을 확보해야 하는 충분한 사유(활동지원사 증가에 따른 교육 및 관리공간 부족, 인근 지역 내 사무공간 확보가 어려운 경우 등)가 있는 경우에는 사업의 원활한 수행을 위해 별도의 사무공간을 마련할 수 있습니다. 다만, 활동지원 수급자 증가 등에 따라 신규 활동지원기관 지정이 필요한 지역임에도 이를 회피하거나 타 지역으로의 사업영역을 확장하기 위한 목적으로 본·지점 등의 기관을 운영하는 것은 기관 지정기준 위반 및 편법적 수단으로 운영될 소지가 있습니다. 따라서 이런 경우에는 복수의 사무실 운영이 제한될 수 있습니다.'),
    ('신청기준및절차', 'A구에서 활동지원기관으로 지정된 후 B구로 소재지를 옮긴 경우, 계속해서 A구 활동지원기관으로 운영 가능한가요?', 'A구에서 활동지원기관으로 운영할 수 없음 활동지원기관의 지정은 특별자치시·특별자치도·시·군·구에서 지정하고 운영되므로 소재지가 관할지역을 벗어난다면 B구에서 새로 지정을 받으셔야 합니다.'),
    ('신청기준및절차', '활동지원기관 관리책임자의 타 사업 업무 겸직 시 인건비는 어떤 방법으로 지급하나요?', '겸직하는 관리책임자는 각 사업의 업무비율에 따라 인건비를 지급 활동지원기관이 ｢장애인복지법｣에 따른 중증장애인자립생활지원센터 및 장애인복지시설, ｢사회 복지사업법｣에 따른 사회복지시설, ｢국민기초생활보장법｣에 따른 지역자활센터 등에 병설하여 운영되는 경우, 활동지원기관 관리책임자는 업무에 지장이 없는 범위 내에서 타 사회복지시설 에 필요한 인력을 겸직할 수 있습니다. 이러한 경우 활동지원기관과 겸직하고 있는 다른 기관 각각 100% 인건비를 지급하는 것은 불가하며, 사회복지시설 종사자 인건비 가이드라인에 따라 책정되는 인건비에 ‘세부업무분담표’에 따른 활동지원사업 업무비율을 적용하여 지급합니다. ※ 예시: 세부업무분담표 상 활동지원 업무 60%, 타 업무 40%의 경우, 60%에 해당하는 금액만을 활동지원사업의 사업비에서 인건비로 집행'),
    ('신청기준및절차', '기존 활동지원기관의 운영 주체가 변경된 경우, 신규로 지정 받아야 하나요?', '권리의무주체 동일 여부 또는 상호 권리관계 일치 여부 등에 따라 판단 단순 명칭 변경이 아닌 법적 권리관계의 변동 또는 상호 권리관계가 일치하지 않는 경우라면, 새로 활동지원기관을 지정받아야 합니다.'),
    ('서비스비용 지급', '활동지원기관이 간접보조사업자에 해당되나요?', '활동지원급여 비용은 간접보조금으로 보기 어려우므로, 활동지원기관을 간접 보조사업자로 볼 수 없음 간접보조금이란 국가 외의 자가 보조금을 재원의 전부 또는 일부로 하여 상당한 반대급부를 받지 아니하고 그 보조금의 교부 목적에 따라 다시 교부하는 급부금을 의미합니다. 활동지원급여 비용은 활동지원기관의 청구에 따라 국가와 지자체가 지급하고는 있으나, 그 금원의 성격이 청구원인에 관계없이 활동지원기관에 직접 교부되는 것이 아니라 활동지원 수급자 개인의 사회서비스 이용비용을 대리 지급하는 것이므로 활동지원기관에 지급되는 급여 비용은 간접 보조금으로 보기 어렵습니다.'),
    ('자격 및 교육', '활동지원기관 운영을 위한 사무실 임대차 보증금을 활동지원사업비로 집행할 수 있나요?', '활동지원기관 운영을 위한 기본경비로 지출 가능함. 단, 보증금 금액 수준 및 계약사항 등을 종합적으로 고려해 기관 운영위원회를 통해 결정 활동지원기관이 자체로 소유한 건물이 없어 임대차를 통해 사무실을 마련해야 하는 경우, 그 보증금 지급을 위한 사업비 집행의 적정성 여부는 임대차 목적물 대비 보증금의 금액 수준과 임대차 계약 종료 시 보증금의 권리주체 및 기관의 재무상태가 보증금 집행에 무리가 없는 상황인지 등을 종합적으로 고려하여 판단할 필요가 있습니다. 또한 이는 활동지원기관 운영 위원회 보고 및 심의를 통해 결정되어야 합니다.'),
    ('자격 및 교육', '활동지원기관이 부적정하게 집행된 사업비에 대한 지자체의 환원 명령 이행 증빙자료 제출 요구에 응하지 않는 경우 지정취소 처분이 가능한가요?', '제출 요구된 자료의 활동지원사업과의 연관성, 부적정 집행에 대한 사실관계 조사 등을 통해 지정취소 등 행정처분 가능 지자체의 장은 활동지원급여 제공내용 확인, 활동지원급여의 관리·평가 등 활동지원사업의 수행에 필요하다고 인정할 때에는 활동지원기관에게 자료 제출을 요구할 수 있고, 활동지원 기관이 자료의 제출 및 질문·검사 요구를 거부·방해·기피하거나 거짓 자료를 제출한 경우 에는 6개월의 범위에서 해당 기관의 업무를 정지하거나 그 지정을 취소할 수 있습니다. (｢장애 인활동 지원에 관한 법률｣ 제24조)'),
    ('신고절차', '활동지원인력이 활동지원급여를 부정수급한 경우, 활동지원기관에 대해 업무정지 처분을 할 수 있나요?', '활동지원기관은 부정수급에 대한 감독의 책임이 있으므로 행정처분이 가능하나, 평소 부정행위에 대한 예방 조치 등을 고려하여 처분하지 않을 수 있음 활동지원기관은 그 종사자가 관계된 부정수급에 대하여 감독의 책임을 가진 자로서 같은 책임이 있습니다. 한편 ｢장애인활동 지원에 관한 법률｣ 제48조에는 활동지원기관이 부정수급 등의 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 형을 과하지 않는다고 명시하고 있습니다. 동 단서에 따라 기관이 부정 행위 예방을 위해 평소 어떠한 조치를 취하였는지 등을 종합적으로 고려하여 행정처분 여부를 판단합니다.'),
    ('신청기준및절차', '활동지원기관의 관리책임자 또는 전담관리인력이 해당기관운영위원회의위원으로위촉될수있나요?', '법적으로 제척되지는 않으나, 공정성·객관성 측면에서 바람직하지 않음 ｢장애인활동 지원에 관한 법률｣ 제22조의2에 따라 활동지원기관의 장은 활동지원기관의 운영에 관한 사항을 심의하기 위하여 기관에 운영위원회를 두어야 합니다. 운영위원은 아래 해당하는 사람 중에서 지자체장이 임명하거나 위촉하고 있으며, 운영위원 결격 또는 제척에 대하여 법률 에서 따로 정하고 있는 바는 없으나 운영위원회를 두도록 한 취지가 활동지원기관의 중요 의사 결정에 대한 공정성과 객관성을 담보하기 위한 것임을 고려하면 해당 기관의 관리·운영 직무 수행자를 운영위원으로 하는 것은 바람직하지 않습니다. 【활동지원기관 운영위원회】 - 위원장 포함 5인 이상 10인 이하로 구성(2년 임기, 한 차례 연임 가능) 구분 운영위원회 구성 위원 다음에 해당하는 사람 중에서 특별자치시장·특별자치도지사·시장·군수·구청 장이 임명·위촉 ▪활동지원기관의 장 ▪활동지원인력 대표 ▪수급자 대표 ▪수급자의 보호자 대표 ▪소속 공무원 중장애인활동지원 업무를 담당하는 사람 ▪지역주민 ▪공익단체에서 추천한 사람 ▪활동지원기관의 운영 또는 장애인활동지원에 관하여 전문적인 지식가 경험이 있는 사람 위원장 활동지원기관의 장을 제외한 나머지 위원 중 호선하여 선정'),
    ('제공기관운영', '활동지원기관 지정에 따른 유효기간이 있나요?', '지자체에서 활동지원기관 지정 시 유효기간을 설정할 수 있음 ｢장애인활동 지원에 관한 법률｣ 제20조에서는 활동지원기관 지정에 대한 절차 등을 정함에 있어 지정에 따른 유효기간은 별도로 정하고 있지 않으며, ｢장애인활동지원기관 등의 지정에 관한 고시｣에서는 고시에서 정한 것 외에 ‘지정에 필요한 사항은 지정권자(특별자치시장·특별 자치도지사·시장·군수·구청장)가 따로 정한다’고 되어 있습니다. 따라서 신규 활동지원 기관을 지정함에 있어 유효기간을 정할 것인지는 해당 지자체의 공모계획 수립 등의 단계에서 자체적으로 결정할 수 있는 사항입니다.'),
    ('사업운영 및 기존정보', '지자체별 적정한 활동지원기관의 수는 어느 정도인가요?', '지역 내 서비스 수요와 공급간 균형, 서비스 이용률 등을 고려하여 판단 ｢장애인활동 지원에 관한 법률｣ 제20조에 따르면 지자체의 장이 활동지원기관의 지역적 분포 및 적정공급 규모, 활동지원급여 수급자 수 등을 고려하여 적정 수의 활동지원기관을 지정하도록 하고 있습니다. 활동지원기관 간 경쟁의 심화 및 운영 부실화를 초래하지 않도록 서비스 이용률, 활동지원사 대기인력 등을 종합적으로 고려하여 지정하는 것이 필요하다 할 것입니다.'),
    ('서비스비용 지급', '활동지원기관의 미사용 퇴직적립금 반납 여부와 가용범위는 어떻게 되나요?', '보조금 및 간접보조금에 해당하지 않아 반납대상으로 보기 어려우며, 고용 노동부 유권해석을 받아 가용범위 확인 필요 활동지원기관이 활동지원서비스 제공에 대한 대가로 청구하여 지급받는 활동지원급여 비용은 ｢보조금 관리에 의한 법률｣에 따른 보조금 또는 간접보조금에 해당되지 않습니다. 따라서 기관 운영경비로 사용되고 남은 잔액이 있더라도 같은 법에 따른 반환 또는 환수 대상으로 보기 어렵습니다. 아울러 활동지원기관이 ｢근로자퇴직급여 보장법｣에 따라 기관 내에 마련해 놓은 적립금에 대한 가용범위는 장애인 활동지원사업 규정만으로는 판단이 어렵고 고용노동부 유권해석을 받아 처리하는 것이 바람직합니다.'),
    ('사업운영 및 기존정보', '활동지원기관 사업비 집행범위를 지침으로 제한하는 이유가 있나요?', '사회복지법인 및 사회복지시설 재무·회계 규칙 준수, 지자체의 관리·감독 등을 통한 최소한의 제한조치를 마련한 것임 활동지원기관 설치 시 관할 지자체로부터 지정을 받도록 하고, ｢사회복지법인 및 사회복지시설 재무·회계규칙｣을 따르도록 한 것은 활동지원기관의 운영과 사업비 집행에 대하여 최소한의 제한조치는 필요하다는 취지입니다. 따라서 사업비 규정을 위반한 활동지원기관에 환수·반환 명령 등 처분을 내릴 법률 상 근거가 없음과는 별개로, 활동지원기관 자율 의사에 의한 사업비 집행은 곤란합니다.'),
    ('제공기관운영', '활동지원기관으로 지정받은 후, 인력 지정기준에 미달되면 행정처분을 받나요?', '활동지원기관 지정 취소 등 행정처분 가능 ｢장애인활동 지원에 관한 법률 시행규칙｣ 제17조 별표1의2에서 활동지원기관 지정에 필요한 인력기준을 정하고 있으며, 동 요건을 충족하지 않게 되면 활동지원기관 지정취소 사유(법률 위반)에 해당합니다.'),
    ('자격 및 교육', '활동지원사와 이용자 사이에 갈등이 발생하는 경우 활동지원기관의 역할은 무엇인가요?', '이용자의 활동지원서비스 범위를 벗어난 서비스 요구가 없었는지, 활동지원사가 이용자의 적정한 요구에도 불구하고 서비스 제공을 거부했는지 등의 내용을 파악하고 충분한 상담을 통해 갈등을 해소하거나 필요시 활동지원사 변경 등의 조치를 취해야 함'),
    ('사업운영 및 기존정보', '활동지원기관이 휴·폐업하는 경우 어떤 절차가 필요한가요?', '휴·폐업 예정일 30일 전까지 지자체에 신고하여야 하며, 활동지원급여 제공 자료의 이관 또는 자체보관 등의 조치 필요 (신고) 폐업하거나 휴업하려는 활동지원기관은 휴·폐업 예정일 30일 전까지 지자체에 신고해야 하며, 휴·폐업 신고를 받은 지자체는 지체 없이 그 내용을 보건복지부, 한국사회보장정보원, 국민연금공단에 통보해야 합니다. (자료이관) 활동지원기관의 장은 기관의 폐업 또는 휴업 예정일 전까지 활동지원급여 제공자료 이관 신청서를 관할 지자체에 제출하고 접수증을 발급받아야 합니다. 이관 대상 자료는 활동 지원급여비용 명세서 복사본, 방문간호지시서, 활동지원급여 제공 계약서, 활동지원급여 제공 기록지 등입니다. (자체보관) 휴업하는 활동지원기관의 장이 활동지원급여 제공 자료를 자체 보관하기 위해서는 휴업 예정일 전까지 활동지원급여 제공자료 자체보관 신청서를 관할 지자체에 제출하고 자체 보관 허가를 받아야 합니다.'),
    ('자격 및 교육', '활동지원사업 수익금을 모법인으로 전출할 수 없다고 되어 있는데, 모법인이란 구체적으로 무엇을 의미하나요?', '기관의 사업자등록번호를 달리하여 운영되는 법인 및 시설로, 활동지원기관을 지배하는 법인을 의미함'),
    ('자격 및 교육', '활동지원사업 수익금을 보험·적금 등 수익증권으로 운용 가능한가요?', '수익증권으로 운용할 수 있음 수익증권으로 운용할 수 있습니다. 단, 활동지원기관의 사업비 수입에서 사업 운영비 등 제반 비용을 지출한 후 남은 수익금의 활용범위는 ｢사회복지법인 및 사회복지시설 재무·회계규칙｣ 에 따라 활동지원기관 운영위원회에 심의·보고 등 절차를 거쳐 확정해야 합니다. 또한 같은 법령에 따라 세입·세출예산 과목을 편성해야 하고 사회복지사업의 공익성과 비영리성을 훼손 하지 않는 범위에서 수입목적의 보험 또는 적금의 금융상품으로 운용이 가능합니다.'),
    ('자격 및 교육', '활동지원사 퇴직적립금을 활동지원기관 운영비로 계상 가능한가요?', '활동지원사 퇴직급여는 활동지원사업 운영을 위한 필수 경비에 해당되므로 당해연도 사업운영 경비로 계상하여 지출 가능'),
    ('서비스비용 지급', '활동지원사와 이용자를 대상으로 명절 선물 및 경조사, 병문안 등에 소요되는 비용을 활동지원 사업비로 지출 가능할까요?', '법령에 따른 통상적인 범위의 금액은 지출 가능. 다만, 이용자에게 지급되는 부분은 각별한 유의 필요 활동지원사업 수익금은, ①활동지원사 임금 ②기본경비, 관리책임자 및 전담관리인력 인건비 ③활동지원사 교육훈련비, 근로조건 개선 등 처우개선을 위한 수당 ④불특정 다수를 대상으로 하는 장애인복지사업에 활용 등의 우선순위에 따라 지출해야 하며, ①,②,③의 비용을 지출한 후 남은 비용을 ④에 해당하는 부분에 지출이 가능합니다. 활동지원사 및 이용자를 대상으로 한 명절 선물, 경조사, 병문안, 견학 등은 ④에 해당할 것이며, 이때 사회상규에 벗어나지 않은 범위 내에서 집행해야 합니다. 특히 이용자 대상 금품 제공은 수급자 알선 또는 유인 행위에 해당될 수 있어 각별한 유의가 필요하며, 지출 전 기관 운영위원회 및 지자체에 사전 보고하는 것이 바람직합니다. 음식물·경조사비·선물 등의 가액 범위 (부정청탁 및 금품 등 수수의 금지에 관한 법률 시행령 제17조제1항) 1. 음식물: 3만원 2. 경조사비: 축의금·조의금은 5만원. 다만, 축의금·조의금을 대신하는 화환·조화는 10만원으로 한다. 3. 선물: 금전, 유가증권, 제1호의 음식물 및 제2호의 경조사비를 제외한 일체의 물품, 그 밖에 이에 준하는 것은 5만원. 다만, ｢농수산물 품질관리법｣ 제2조제1항제1호에 따른 농수산물(이하 “농수산물”이라 한다) 및 같은 항 제13호에 따른 농수산가공품(농수산물을 원료 또는 재료의 50퍼센트를 넘게 사용하여 가공한 제품만 해당하며, 이하 “농수산 가공품”이라 한다)은 10만원(제17조제2항에 따른 기간 중에는 20만원)으로 한다.'),
    ('자격 및 교육', '활동지원사 교육기관 지정절차는 어떻게 되나요?', '‘지자체 공모 계획 수립·공고 → 신청접수 → 현지확인 → 심사위원회 개최 → 선정 및 지정 → 전산입력 → 활동지원사 교육기관 지정서 발송 → 공단 등 통보 ’의 절차를 통해 지정됩니다. 활동지원사 교육기관으로 지정받고자 신청하는 경우에는 반드시 아래의 시설 및 인력기준을 갖춘 후 신청해야 합니다. 구분 분류 충족 기준 시설 기준 입지 활동지원사 수요, 교육기관 분포 적정성 등이 고려된 적절한 위치 해야 함 강의실 교육과정 운영에 필요한 공간을 마련해야 하며, 강의실에는 시청각 및 실기 교육에 필요한 기자재를 갖춰야 함 사무실 교육과정 관리 및 교육생에 대한 상담에 필요한 공간을 마련해야 하며, 사무실 내에는 통신설비, 집기 등 업무에 필요한 설비·비품을 갖춰야 함 기타 - 채광, 환기, 조명, 온도를 적절히 유지할 수 있는 시설을 갖춰야 함 - 시설규모에 맞는 적절한 화장실과 급수시설을 갖춰야 함 - 화재예방, 소방시설 설치·유지 및 안전관리에 관한 법률에 따른 소방시설을 갖춰야 함 인력 기준 관리책임자 1명 전담관리인력 1명 이상 교수인력 1명 이상 지자체는 ｢장애인활동지원기관 등의 지정에 관한 고시｣에서 정한 심사기준에 따라 심사하며, 심사결과 80점 이상 득점, 고득점 순으로 지정기관을 선정합니다. 구분 심사항목 배점 기관현황 사회복지법인 등 설치 기관(법인)의 공익성 10 기관의 관할 시·도 내 접근성, 지역적 분포 10 최근 3년간 교육 제공 실적 5 교육운영능력 교육 강사진 확보 및 구성 현황 15 교육 전담인력 확보 현황 10 강의실 및 교육 기자재 등 교육여건 10 교육관리계획 교육 계획 10 예산 조달방안 등 사업운영계획의 타당성 10 자체 사업평가 계획의 타당성 10 기타 지자체별 자체평가 기준 10 합계 100 감점 행정지도 및 민원 5'),
    ('신청기준및절차', '교육기관의 수익금을 다른 사업에 활용할 수 있나요?', '활동지원기관의 사업비 지출 가능범위에 준하여 판단함 교육기관 자체 운영 규정을 별도로 정하여 수익금을 활용해야 하며 운영 수익금에 대한 구체적인 가이드라인은 없습니다. 다만, 활동지원기관 수익금 활용범위를 준용해 볼 때, 교육기관의 수입은 전담 및 교수인력 등 인건비, 사회보험료, 퇴직금, 공공요금 및 사무실에 대한 운영유지비 등 교육에 필요한 경비에 지출해야 합니다. 필요경비 지출 후 남은 금액은 모법인, 다른 사업 교육기관으로의 전출은 금지하며, 활동지원사 교육기관 운영의 세입으로 계상하여 활동지원사 교육사업에 한하여 사용해야 합니다.'),
    ('자격 및 교육', '활동지원사 PART 5 활동지원사란 누구인가요?', '활동지원사 교육기관에서 교육과정을 모두 수료하고, 장애인에게 활동보조 서비스를 제공하는 인력을 의미함'),
    ('자격 및 교육', '활동지원사가 되기 위해서는 어떤 과정이 필요한가요?', '활동지원사 교육기관에서 이론·실기 교육 및 활동지원기관에서 실습 교육을 모두 이수하여야 활동지원사 자격을 취득함 교육과목 및 시간은 아래와 같으며, 활동지원사 교육기관 및 교육일정, 활동지원기관 등은 장애인 활동지원 홈페이지(http://www.ableservice.or.kr)에서 확인하실 수 있습니다. 과목 교육내용 교육시간 이론 실기 활동지원개론 (8시간) 장애의 이해 2 - 자립생활과 활동지원의 이해 2 - 장애와 인권 2 - 활동지원사의 인권과 직업윤리 2 - 활동지원서비스 기초 (19시간) 신체적 장애인의 장애유형별 활동지원 2 2 정신적 장애인의 활동지원 2 2 보조기기의 이해 2 2 장애인의 건강과 대처방법 1 2 응급상황과 대처방법 2 2 활동지원의 실제 (13시간) 활동지원의 실제 2 - 일상 및 사회활동 지원 2 2 의사소통 지원 2 2 서비스 제공기록 및 관리 1 2 소계 24 16 현장실습(10시간) 활동지원기관 현장실습 10 총계 50'),
    ('자격 및 교육', '2011년 활동지원제도 시행 전 시범사업 기간에 활동지원사로 채용되어 서비스를 제공한 경우 활동지원인력의 자격요건을 충족한 것으로 볼 수 있나요?', '장애인활동 지원에 관한 법률 시행규칙 부칙(보건복지부령 제72호) 제2조에 의거, 시범사업 기간에 활동보조인 자격을 갖추고 활동한 사람은 현재의 활동지원사 자격을 충족한 것으로 인정'),
    ('자격 및 교육', '당뇨병, 간염보균자 등 특정 질병이 있는 사람도 활동지원사로 근로할 수 있나요?', '활동지원사로 근로할 수 있음. 다만, 감염성 질환의 경우는 전염성이 없다는 의사의 소견서 필요'),
    ('자격 및 교육', '활동지원사의 결격사유 또는 연령 제한이 있나요?', '활동지원사의 연령 제한은 없으며, 장애인활동 지원에 관한 법률 제29조에서 활동지원사의 결격사유를 정하고 있음. 또한 결격사유와 별도로 활동지원급여 수급자 등은 활동지원사가 될 수 없음 【활동지원사】 구분 대상 활동지원사 결격사유 ▪ ｢정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률｣ 제3조제1호에 따른 정신질환자(전문의가 활동지원사로 적합하다고 인정하는 사람은 제외) ▪ 마약·대마 또는 향정신성 의약품 중독자 ▪ 피성년후견인 또는 피한정후견인 ▪ 금고 이상의 형을 선고받고 그 형의 집행이 끝나지 아니하였거나 그 집행을 받지아니하기로 확정되지 아니한 사람 ▪ ｢성폭력범죄의 처벌 등에 관한 특례법｣ 제3조부터 제10조까지 및 제15조에 규정된 죄로 금고 이상의 형을 선고받은 사람 ▪ ｢장애인활동 지원에 관한 법률｣ 제30조제1항제2호에 해당하여 활동지원인력 자격이 취소된 날부터 1년이 지나지 아니한 사람 ▪ ｢장애인활동 지원에 관한 법률｣ 제30조제1항제3호부터 제5호까지에 해당하여 활동지원인력 자격이 취소된 날로부터 2년이 지나지 아니한 사람 결격사유 외 활동지원사가 될 수 없는 사람 ▪ 활동지원급여 수급자, 장기요양급여 수급자 ▪ 활동지원기관이 아닌 사회복지시설의 장 또는 종사자 ▪ ｢노인장기요양보험법｣ 상 재가장기요양기관의 장 또는 종사자(장기요양요원은 제외) ▪ 활동지원기관의 장, 관리책임자, 전담관리인력 등 활동지원인력이 아닌 활동'),
    ('신고절차', '지원기관 종사자 활동지원사 자격이 취소되거나 정지될 수 있는 사유는 무엇인가요?', '구분 대상 활동지원사 자격취소 사유 ▪ 결격사유에 해당되는 사람(84번 질문 참고) ▪ 거짓이나 그 밖의 부정한 방법으로 활동지원사가 된 경우 ▪ 업무수행 중 고의 또는 중대한 과실로 수급자 또는 그 보호자에게 신체상 또는 재산상 손해를 입혀 금고 이상의 형을 선고받아 판결이 확정된 경우 ▪ 자격정지 처분을 3회 이상 받은 경우 ▪ 자격정지 기간 중 활동지원급여를 제공한 경우 활동지원사 자격정지 사유 ▪ 수급자에게 지급된 활동지원급여 이용권을 그 목적 외의 용도에 사용하게 한 경우 ▪ 수급자를 소개·알선·유인하는 행위 및 이를 조장하는 행위를 한 경우 ▪ 수급자의 신체에 폭행을 하거나 상해를 입히는 행위 ▪ 수급자에게 성적 수치심을 주는 성폭행·성희롱 등의 행위 ▪ 자신이 활동지원급여를 제공하는 수급자를 내다 버리거나 의식주를 포함한 기본적 보호 및 간병 등을 소홀히 하는 행위 ▪ 거짓이나 그 밖의 부정한 방법으로 활동지원급여 비용을 받은 경우'),
    ('자격 및 교육', '외국인도 활동지원사로 근로할 수 있나요?', '체류자격 F-2(거주), F-4(재외동포), F-5(영주), F-6(결혼이민), H-1(관광 취업), H-2(방문취업)인 외국인의 경우 활동지원사로 근로 가능 활동지원기관은 외국인을 활동지원사로 채용하려는 경우 외국인등록증 또는 거소증으로 체류 자격 등 출입국 관계 법령 위반 여부를 확인하여야 합니다. 또한 수급자의 권익 보호를 위하여 해당 외국인의 결격사유 여부와 서비스 내용을 고려한 의사소통 가능여부 등도 확인해야 합니다. 체류자격 H-2 외국인을 채용하고자 하는 활동지원기관의 경우, 활동지원기관이 해당 비자 소지자에게 허용된 업종(사회복지서비스업, 개인간병인 및 유사 서비스업 등)으로 사업자등록이 되어있어야 하며, 관할 고용센터로부터 외국인 고용 허가를 사전에 취득해야 합니다.'),
    ('자격 및 교육', '활동지원급여 제공이 제한되는 가족의 범위는 어떻게 되나요?', '활동지원사 본인을 기준으로 민법 제779조(가족의 범위)의 관계에 있는 수급자 에게는 활동지원급여를 제공할 수 없음 활동지원사 기준으로 서비스를 제공하면 안되는 사람은 아래와 같습니다. 구분 세부 대상 배우자 남편, 아내 (※ 사실혼 포함) 직계혈족 (외)할아버지, (외)할머니, 아버지, 어머니, 아들, 딸, 손자, 손녀 등 형제·자매 오빠, 형, 언니, 누나, 남동생, 여동생 직계혈족의 배우자 며느리, 사위, 손자며느리, 손녀사위, 계부모 등 배우자의 직계혈족 시어머니, 시아버지, 장인, 장모, 계자녀 등'),
    ('신청기준및절차', '배우자의 형제·자매 시숙(위, 아래), 시누이(위, 아래), 처남(위, 아래), 처형, 처제 등 가족에 의한 활동지원급여 제공을 제한하는 이유는 무엇인가요?', '장애인의 자립생활 지원이라는 제도 취지에 맞지 않음 활동지원제도는 장애인의 자립생활을 지원하고 그 가족의 부담을 줄임으로써 장애인의 삶의 질을 높이는 것을 목적으로 합니다. 활동지원급여를 가족에게 지급할 경우 장애인에 대한 직접 적인 서비스보다 생계유지를 위해 현금화되어 그 목적이 변질될 우려가 있고, 실질적인 급여 제공 여부 판단 및 서비스의 질적 수준 확보에 곤란이 있는 등 장애인의 자립생활 지원을 저해할 수 있는 다양한 문제점이 있습니다. 다만, 활동지원사로부터 서비스를 받기 어렵다고 인정되는 경우에는 예외적으로 가족에 의한 활동지원급여 제공을 허용하고 있습니다.'),
    ('자격 및 교육', '가족에 의한 활동지원급여 제공이 가능한 케이스가 있을까요?', '아래의 어느 하나에 해당하고 활동지원사로부터 서비스를 제공받기 어렵다고 인정되는 경우에는 가족에 의한 활동지원급여 제공이 가능 1) 수급자가 섬, 벽지 등 활동지원기관이 부족한 지역에 거주하는 경우 2) 활동지원기관(인력)이 부족한 농어촌지역 거주로 서비스 이용에 어려움이 있어 지자체에서 예외적으로 가족에 의한 급여 제공을 허용한 경우 - 지역 내 활동지원기관(인력) 현황, 수급자 선정 및 급여 제공 신청 후 대기시간 등을 고려 하여 허용 3) 수급자가 ｢감염병의 예방 및 관리에 관한 법률｣에 따른 감염병 환자로서 감염 위험이 있음이 증빙서류에 의해 증명되는 경우(제1~4급 감염병, 기생충감염병, WHO 감시대상 감염병, 생물테러감염병, 성매개감염병 등) 4) 천재지변 또는 이에 준하는 사유가 있는 경우'),
    ('자격 및 교육', '활동지원사가 이복형제에게 서비스 제공이 가능한가요?', '활동지원사 기준으로 급여 제공이 제한되는 가족의 범위(형제·자매)에 해당 하므로 서비스 제공 불가 부·모계 형제·자매 중 특정 대상을 가족의 범위에서 제외한다는 규정이 별도로 없고, 대법원 판례에서도 민법상 형제·자매는 부계 및 모계의 형제·자매를 모두 포함하고 있으므로 이복 형제의 경우에도 활동지원서비스 제공이 제한되는 가족의 범위에 포함됩니다.'),
    ('자격 및 교육', '활동지원사가 이혼 및 재혼으로 새로운 배우자와 가족관계를 형성한 경우, 전 배우자의 손녀에게 서비스 제공이 가능한가요?', '전 배우자의 손녀에게 서비스 제공 불가 전 배우자와의 관계에서 생겨난 자녀와 손자녀는 이혼 및 비동거 하더라도 직계혈족의 관계에는 변함이 없으므로 서비스 제공이 제한되는 가족의 범위에 포함됩니다.'),
    ('자격 및 교육', '활동지원사의 남편이 사망한 경우, 남편의 형제인 시동생에게 서비스 제공이 가능한가요?', '사망한 남편의 시동생에게 서비스 제공 불가 민법에 의하면 인척관계는 혼인의 취소 또는 이혼으로 종료되며 부부의 일방이 사망한 경우에는 소멸되지 않는다고 규정하고 있으므로, 배우자가 사망하더라도 시동생은 배우자의 형제·자매 관계에 변함이 없으므로 서비스 제공이 제한되는 가족의 범위에 포함됩니다. 기타 문의'),
    ('바우처 사용 방법', '제공되는 활동지원서비스 시간이 부족한 경우 추가로 바우처를구매할수있나요?', '이용자와 활동지원기관 간의 자율적 계약에 의해 전액 수급자 부담으로 바우처 추가 구매하여 이용 가능 수급자에게 제공되는 바우처 보다 더 많은 급여를 원할 경우에는 활동지원기관과 별도의 계약을 체결 후 서비스를 이용할 수 있습니다. 서비스 제공 전 활동지원기관은 해당 사실을 지자체에 신고해야 하며, 추가 구매 내역에 대해서는 바우처 카드를 활용한 결제는 불가합니다.'),
    ('대상자정보', '활동지원급여 수급자격이 상실되거나 급여 제공이 중단되는 경우가 있나요?', '아래의 수급자격 상실 및 급여 제공 중단 사유 참조 수급자가 활동지원급여 수급 중 상실 사유에 해당하게 된 경우 수급자격이 종료되며, 잔여 유효기간이 남아 있더라도 활동지원급여를 받을 수 없습니다. 수급자가 활동지원급여 수급 중 중단 사유에 해당하게 된 경우 수급자격은 유지하되, 해당 기간에 활동지원급여의 지급은 중단됩니다. 구분 내용 활동지원 수급자격 상실 사유 ▪ 사망 ▪ 국적상실 또는 국외이주 ▪ 장애등록의 취소 ▪ ｢노인장기요양보험법｣ 제2조제1호에 따른 노인 등에 해당 ▪ 활동지원급여 수급자격 유효기간 만료(유효기간 만료 후 신청자격에 해당 시 신규신청 가능) 활동지원급여 중단 사유 ▪ ｢국민기초생활 보장법｣에 따른 보장시설 입소 ▪ ｢형의 집행 및 수용자의 처우에 관한 법률｣ 또는 ｢치료감호 등에 관한 법률｣에 따른 교정시설 또는 치료감호시설에 수용 ▪ 체류기간이 60일 이상 지속되는 국외체류 ▪ 60일 초과하여 의료기관에 입원 ▪ 다른 법령에 따라 활동지원급여와 비슷한 급여를 받고 있다고 보건복지부 장관이 인정하는 경우(가사간병방문지원, 노인맞춤돌봄서비스, 장애아가족 양육지원 등) ▪ 수급자가 급여 중단을 신청할 때 ▪ 6개월 이상 연속하여 급여를 이용하지 않았을 때'),
    ('자격 및 교육', '활동지원급여 수급자격 변동에 대한 신고는 누가 해야 하나요?', '수급자격 변동에 대한 신고의무자에는 수급자, 수급자의 보호자, 활동지원사, 활동지원기관 전담관리인력 등이 있음 활동지원급여 수급 중 인적사항 및 소득·재산의 변동, 수급자격 상실 또는 급여의 중단 사유, 부당지급급여 발생과 관련된 일체의 사항이 발생하면 신고의무자는 지체없이 해당 지자체에 신고해야 합니다.'),
    ('자격 및 교육', '부당지급급여가 발생한 경우, 활동지원기관의 고의나 과실이 없어도 활동지원기관을 대상으로 징수할 수 있나요?', '활동지원기관은 고의 및 과실이 없어도 부당지급급여의 징수대상이 됨 활동지원기관은 활동지원사 및 수급자에 대한 정보 관리, 교육, 근로계약 체결 등 사업 전반을 실질적으로 관리하고 있으며, 활동지원사 및 수급자와의 관계를 사용자와 피사용자 등의 관계로 볼 수 있어 활동지원기관을 대상으로 부당지급급여 징수가 가능합니다. 활동지원사 및 수급자에게 귀책 사유가 있는 경우에는 활동지원기관이 활동지원사 등에게 구상권을 행사할 수 있습니다.'),
    ('신고절차', '수급자가 주간보호시설에서 급여를 이용한 경우, 차량 운행일지 등을 근거로 시설 내 이용에 대한 환수조치가 가능한가요?', '환수조치 가능함 공동생활가정(그룹홈)·단기거주시설 거주 장애인 및 주간보호시설 이용 장애인은 시설 밖에서 활동지원급여를 이용해야 합니다. 시설 내 이용에 대한 구체적인 증빙자료가 없는 경우에는 당사자 간 계약 또는 시설 운영규정에서 정한 이용시간 등을 종합적으로 고려하여 환수조치 여부를 판단합니다. 참고로 주간보호시설 이용시간은 평일 오전 9시부터 오후 18시까지이며, 보호자의 요청과 시설 운영규정 내에서 이용시간 조정이 가능하도록 정하고 있습니다.'),
    ('신고절차', '수급자가 장애인 등록이 취소된 후에도 계속 수급하다가 사망한 경우, 그 가족을 대상으로 환수가 가능한가요?', '환수 불가함 (수급자가 급여비용의 반환처분을 받아 급여 반환채무가 생긴 후 사망한 경우에는 그 상속인이 급여비용 반환채무를 상속하지만, 반환처분을 받기 전에 사망한 경우에는 상속인을 대상으로 환수 불가) 급여비용 징수요건에 해당하는 행위의 효과가 상속인에게 승계된다는 규정을 두고 있지 않아 급여비용의 반환을 명하는 처분은 수급자 또는 활동지원기관에 한하여 할 수 있고 그 상속자 에게는 할 수 없습니다.'),
    ('신청기준및절차', '검찰 수사로 인해 기소되거나 경찰에서 수사 중인 사건인 경우 징수는 언제부터 가능한가요?', '사건처리 결과 통지를 받음과 동시에 징수 가능함'),
    ('신고절차', '조례를 통해 시·도 또는 자치구 예산으로 활동지원급여 추가 지원이 가능한가요?', '지방의회에서 사무에 관한 조례를 제정하거나 지자체장의 규칙 마련 등을 통해 지자체 재원으로 활동지원급여 추가 지원 가능 부록 활동지원급여 부정수급 사례 PART 7 활동지원급여 부정수급 공모한 활동지원사 및 수급자(보호자) 벌금형사례1 활동지원 급여비용을 허위로 청구해 수천만 원을 부정수급한 혐의로 재판에 넘겨진 활동지원사 A씨에게 벌금형이 선고되었으며, 범행을 공모해 기소된 장애인 자녀의 부모 B씨도 동일한 형을 받았습니다. A씨는 2018년 11월부터 약 2년간 활동지원서비스를 제공하지 않았음에도 726회에 걸쳐 급여비용 약 3,380만 원을 ○○IL센터에 청구하여 급여 비용을 수급했습니다. 범행을 공모한 B씨는 부정수급한 급여비용 중 절반을 A씨로부터 받은 것으로 확인 됐습니다. 또한 A씨는 2020년 11월에도 C씨와 공모해 동일한 방법으로 96회에 걸쳐 약 440만 원의 급여비용을 부정수급 하였고, 벌금형과 별개로 부정수급한 급여비용은 전액 환수 행정처분 및 활동지원사 자격도 정지되었습니다. 활동지원급여 부정수급한 활동지원사 및 수급자 집행유예 처분사례2 활동지원 급여비용을 허위로 청구하여 부정수급한 활동지원사 A씨가 징역 6월, 집행 유예 1년 및 사회봉사 120시간을 선고받았습니다. A씨는 2018년 1월부터 7월까지 약 268회에 걸쳐 활동지원서비스를 제공하지 않고 급여비용 약 1,100만원을 ○○활동지원센터에 청구하여 이를 수급한 혐의로 재판에 넘겨졌습니다. A씨는 장애인인 제부 B씨의 바우처카드를 받아 서비스를 제공하지 않고 바우처를 결제하는 수법으로 급여비용을 챙겼으며, A씨의 범행을 도운 혐의로 기소된 B씨 역시 징역 4월에 집행유예 1년을 선고받았습니다. 활동지원급여 부정수급한 활동지원사 및 수급자 집행유예 처분사례3 활동지원기관장 A씨, 기관 직원 B·C·D씨, 활동지원 수급자의 보호자 E씨 등이 활동지원급여를 부정수급한 혐의로 불구속 입건되었습니다. C씨는 2013년 3월부터 2016년 1월까지 기관장 A씨의 활동지원사로 근로하면서 같은 기관 직원인 친언니 B씨가 서비스를 제공한 부분까지 청구해 급여비용 3,750만 원을 부정수급한 혐의, D씨는 활동지원기관에 명의를 빌려주고 지체장애를 갖고 있는 E씨의 딸에게 서비스를 제공한 것처럼 속여 1,000여만 원의 지원금을 받아 일부 금액을 E씨 에게 준 혐의를 받았습니다. D씨는 지원금에 따라 일정 비율을 B씨에게도 전달한 것으로 알려졌습니다. 부정수급한 급여비용은 전액 환수 조치되었고, 기관장·활동지원사는 자격이 정지 되었습니다. 시각장애인 가족과 활동지원사 담합에 의한 급여비용 부정수급사례4 시각장애인 A씨는 배우자, 오빠, 사촌동생이 시각장애인인 것을 이용해 활동지원사와 담합하여 서비스를 제공·이용하지 않고 바우처를 허위 결제하여 2009년 9월부터 2016년 3월까지 4억 2천여만원의 급여 비용을 부정수급하였으며, 부정수급한 급여 비용은 시각장애인들과 활동지원사가 일정 비율로 나눠 가진 것으로 확인되었습니다. A씨는 활동지원사에게 본인의 바우처 카드를 주고 허위결제하도록 하였으며, 결제된 시간에 활동지원사는 다른 생업에 종사하고 있었습니다. A씨 및 그 가족들은 서비스 중지, 활동지원사는 자격이 중지되었습니다. 활동지원사의 이용자 바우처카드 소지 후 허위결제 Ⅰ사례5 활동지원사 A씨는 평일에 4시간씩 가사지원서비스를 제공하면서 이용자의 보호자 동의를 받아 이용자 바우처 카드를 소지하고 다녔습니다. 개인사정으로 화요일에 서비스를 제공하지 못하게 되자 월요일에 8시간 서비스 제공 후 이중 4시간만 결제하고, 서비스를 제공하지 않은 화요일에 자택에서 4시간을 허위로 결제하였습니다. 현장점검을 통해 이용자 바우처 카드 소지 및 화요일 4시간 허위결제로 부정수급 환수 조치되었습니다. 활동지원사의 이용자 바우처카드 소지 후 허위결제 Ⅱ사례6 활동지원사 A씨는 이용자 B씨에게 매일 서비스를 제공하는 것으로 계약을 하였으나, B씨의 인지능력이 다소 낮다는 사실을 알고는 실제 서비스를 제공하지 않고 바우처 허위결제를 해왔습니다. 활동지원기관에서 서비스 관리를 위해 이용자 자택을 방문해 보니 집안 관리 상태가 엉망인 점으로 미루어 정상적인 서비스가 제공되지 않았음을 확인하고, 이를 한국 사회보장정보원 전자바우처클린센터로 신고하였습니다. 현장점검에서 활동지원사 A씨는 부정수급 사실을 완강히 부인하였으나, 추후 수사의뢰 예정임을 안내하자 평소 이용자 바우처 카드를 소지하고 다니면서 대부분 서비스 제공 없이 결제만 하였음을 시인하였고, 지자체는 부정수급 전액 환수 및 활동지원사 자격 정지 행정처분을 내렸습니다. 활동지원사의 이용자 바우처카드 소지 후 허위결제 Ⅲ사례7 활동지원사 A씨는 평소 아동 이용자 B씨의 바우처 카드를 소지하면서 등하교지원 서비스만 제공하였고, 월 바우처 시간이 많이 남는 것을 알고는 수업시간 중 서비스를 제공한 것처럼 결제하였습니다. 학교 수업 중 발생한 결제는 한국사회보장정보원 모니터링 시스템으로 탐지되어 부정 수급으로 적발되었습니다. 수년에 걸친 부정수급으로 활동지원사 자격정지 및 이용자의 서비스 이용이 중지되었으며, 관리 감독 소홀에 대한 책임으로 제공기관은 영업정지 등 행정처분을 받았습니다. 활동지원사의 이용자 바우처카드 소지 후 허위결제 Ⅳ사례8 현장점검 시 활동지원사 A씨의 교육시간과 서비스제공 시간이 겹치는 것을 확인하여 추가 조사한 결과, A씨는 보수교육 참석 시간 동안 바우처 결제를 하였고 평소 지적 장애인인 이용자의 바우처 카드를 소지한 부분이 확인되었습니다. 그뿐만 아니라 본인의 출퇴근 시간 등 1~2시간 정도를 이용자가 눈치채지 못할 정도로 치밀하게 계획하여 초과 결제했습니다. 부정수급은 전액 환수 조치되었고, 활동지원사 A씨는 자격정지 처분을 받았습니다. 이용자의 활동지원사 바우처카드 소지 후 허위결제 사례9 활동지원사 A씨는 지인의 소개로 알게 된 이용자 B씨와 매칭되는 조건으로 활동지원 기관과 계약을 체결하였습니다. 이용자 B씨는 활동지원사의 단말기와 바우처카드를 소지하면서 서비스를 받지 않고 허위로 결제하였습니다. 담합하여 허위 결제한 비용은 A씨와 B씨가 서로 나누어 가졌 으며, 이는 한국사회보장정보원 모니터링 시스템 확인 및 현장점검을 통해 부정수급 으로 적발되었습니다. 부정수급된 급여비용은 전액 환수조치 되었으며, 활동지원사 자격 중지 및 이용자 서비스 중지 등의 행정처분이 내려졌습니다. 활동지원서비스를 제공할 수 없는 가족에게 서비스 제공Ⅰ사례10 장애인 자녀를 둔 A씨는 활동지원사업을 운영하는 ‘○○○장애인부모회’의 기관장으 로서 본인의 자녀 B씨를 이용자로 등록하고, 소속 활동지원사 C씨가 본인의 자녀 B씨 에게 서비스 제공 없이 결제만 하도록 하여 급여를 나누어 가졌습니다. 또한 기관장 A씨는 부모회라는 기관 특성상 장애인 자녀를 둔 활동지원사들이 많다는 사실을 악용하여, 활동지원사가 본인의 자녀를 돌보면서 바우처 결제는 실제 서비스를 계약한 다른 부모(활동지원사)의 카드로 결제해도 된다며 부정행위 방법을 전파한 사실도 확인되었습니다. 관할 지자체는 건전한 바우처 이용을 관리해야 하는 제공기관 의무를 심각하게 위반한 사안임에 따라 부정수급 환수조치 뿐만 아니라 제공기관 폐쇄 등의 조치를 하였습니다. 활동지원서비스를 제공할 수 없는 가족에게 서비스 제공Ⅱ사례11 장애 자녀를 둔 부모 A씨는 아파트 단지 내 다른 장애 자녀를 둔 부모 B씨에게 접근하여 본인의 자녀를 돌보면서 공짜로 돈을 받을 수 있다고 설득하여 ○○○센터의 활동 지원사로 등록하도록 하고 서로 상대방의 자녀와 서비스 계약을 체결하였습니다. A씨와 B씨는 각자 본인의 자녀를 돌보면서 활동지원사 바우처카드를 맞바꿔 정해진 시간에 맞추어 결제하는 등 치밀하게 부정수급을 하였으나, 한국사회보장정보원의 모니터링으로 허위결제 정황이 포착되어 현장점검을 통해 적발되었습니다. 부정수급한 급여비용 전액 환수, 활동지원사 자격정지 및 이용자 서비스 중지 처분을 받았습니다. 활동지원사의 이용자 바우처카드 소지 후 초과결제사례12 이용자 A씨는 직장 근로자로서 활동지원사 B씨로부터 가사지원과 B씨의 차량을 통한 출·퇴근 이동서비스를 받고 있었습니다. 매일 차량을 지원받아 고마운 마음에 A씨는 B씨에게 바우처 카드를 맡기며 교통지원금 명목으로 하루 1시간씩 초과로 결제하라고 권유했습니다. B씨가 출근 또는 퇴근 후 자유롭게 매일 1시간씩 초과 결제한 이력은 한국사회보장 정보원 모니터링에 적발되었습니다. 해당 지자체는 활동지원사 자격정지 및 이용자 서비스 중지 처분하고, 지급된 바우처 급여는 환수 조치하였습니다. 적정한 서비스 범위를 벗어나 활동지원서비스를 제공한 사례사례13 안마원을 운영하면서 안마사로 근무하는 시각장애인 A씨는 본인의 활동지원사 B씨와 안마원으로 함께 출근하면서 안마원 청소, 안마원의 세탁물 세탁, 고객 안내, 비용 결제 등 안마원 운영에 필요한 업무에 대해 활동지원사로부터 도움을 받았습니다. 활동지원사가 규정된 활동보조서비스(신체, 가사, 사회활동 등) 외 이용자의 생업을 지원하는 것은 지침 위반사항으로, 해당되는 급여비용은 환수 조치되었습니다. MEMO 발행처 국민연금공단 장애인지원실 장애인서비스지원부 발 행 2022. 11. 주 소 54870 전라북도 전주시 덕진구 기지로 170(만성동) 전 화 국번없이 1355 홈페이지 http://www.nps.or.kr(국민연금공단) http://www.ableservice.or.kr(장애인 활동지원)')
) AS v(subcategory, question, answer);

-- ── 확인 ─────────────────────────────────────────────────
\echo ''
\echo '=== 시간대별 (오늘) ==='
SELECT EXTRACT(HOUR FROM created_at)::int AS hour, COUNT(*)
FROM calls WHERE created_at >= date_trunc('day', now()) GROUP BY 1 ORDER BY 1;
\echo '=== 상태별 ==='
SELECT status, COUNT(*) FROM calls WHERE source_request_id LIKE 'DEMO-%' GROUP BY 1 ORDER BY 2 DESC;
\echo '=== 상담사 상태 근거 (최근 7일) ==="'
SELECT co.name, COUNT(*) AS calls,
       ROUND(AVG(c.counselor_negative_score)::numeric, 3) AS neg_avg,
       COUNT(*) FILTER (WHERE ar.grade ->> 'value' = '악성콜') AS malicious
FROM calls c JOIN counselors co ON co.id = c.counselor_id
JOIN analysis_results ar ON ar.call_id = c.id
WHERE c.source_request_id LIKE 'DEMO-%' AND c.call_started_at >= CURRENT_DATE - 6
GROUP BY co.name ORDER BY calls DESC;
